INSERT INTO `dc_tunables` (`category`, `name`, `d3_value`, `tuned_value`, `unit`, `notes`) VALUES
('affixes', 'missile_dampening_rollable', NULL, 0.0, 'flag', 'Section B audit line 585, Architect ruling 2026-09-19: whether Missile Dampening is in the roll pool is an engine-feasibility switch of ours, not D3 pool membership. 3.3.5a has no per-projectile speed control, so it is excluded rather than left a no-op that eats a Rare pack''s one Defensive slot; set it to 1 when the engine can carry it. D3 pool membership stays sourced in elite_affix_pools.csv'),
('barbarian', 'health_potion_cooldown_seconds', 30.0, NULL, 'seconds', 'from legendary_potions.csv:d3_id=HealthPotionLegendary_01.cooldown_s, reference/d3planner/data.json /potions'),
('barbarian', 'health_potion_heal_pct', 60.0, NULL, 'percent', 'from legendary_potions.csv:d3_id=HealthPotionLegendary_01.base_heal_pct, this row''s own base_heal column: "60% of max Life", and every other row in this file says the same. Audit row 26'),
('combat', 'active_skill_slots', 6.0, NULL, 'count', 'from character_rules.csv:name=active_skill_slots.value, Diablo Wiki https://diablo.fandom.com/wiki/Elective_Mode - "allows players to freely assign any unlocked skills to any of the six action bar slots"; corroborated by https://diablo.fandom.com/wiki/Active_skill. Sourced by Gemini, docs/research/literal-audit-sources-2.md row 22'),
('combat', 'ahavarion_chance_pct', NULL, 10.0, 'percent', 'Ahavarion, Spear of Lycander (legendary 052): the chance, in percent, that killing a demon gives one random shrine buff. D3''s text says only ''Chance on killing a demon'' and gives no number; the Power file docs/research/legendary-pow-data.csv ItemPassive_Unique_Ring_672_x1.pow has SF_0 Chance % = 0.005 in a unit it does not state, so the number is the designer''s: 10 (card q-1016-20). 0 never, 100 always; set at run time with `.dc tunables set combat ahavarion_chance_pct <n>`'),
('combat', 'area_damage_chance', 0.2, NULL, 'multiplier', 'from damage_formula.csv:step=11. Area Damage Proc (Secondary).area_damage_chance, this row''s own formula column: "If Random(0 1) < 0.20"; 02-combat section 2. Audit row 1'),
('combat', 'area_damage_radius_yards', 10.0, NULL, 'yards', 'from damage_formula.csv:step=11. Area Damage Proc (Secondary).area_damage_radius_yards, this row''s own notes_on_buckets column: "all enemies within 10 yards". Audit rows 2, 3 and 4'),
('combat', 'big_life_hit_messages_per_second', NULL, 8.0, 'count', 'diablocraft-l9s9 (docs/contracts/big-life-messages.md): the most H records (up to 10 hits each) the server sends one player in a second. Beyond it the waiting hits fold into one sum, so the cap is a hard cap on traffic. PLACEHOLDER: the report seeds 8 (4 per second expected at 10 such hits per second); the designer sets it. Blank or 0 would send no H record, and the combat text keeps the clamped number.'),
('combat', 'big_life_pull_burst', NULL, 5.0, 'count', 'diablocraft-l9s9 (64-bit Life bead 5; report big-life-2026-10-07 section 3.4): DCBIGLIFE pull requests (the addon asks for the true max Life of a target whose UnitHealthMax is 1000000000) a player may send at once. PLACEHOLDER: the report seeds ''at most 1/s per player''; 5 lets a few quick retargets through. The designer sets it. Blank would mean the route refuses every request (docs/contracts/window-bridge.md, Budget).'),
('combat', 'big_life_pull_per_second', NULL, 1.0, 'count', 'diablocraft-l9s9 (64-bit Life bead 5; report big-life-2026-10-07 section 3.4): DCBIGLIFE pull tokens per second a player gets back. PLACEHOLDER: the report seeds ''at most 1/s per player''; the designer sets it. Blank would mean the route refuses every request (docs/contracts/window-bridge.md, Budget).'),
('combat', 'big_life_window_ms', NULL, 250.0, 'milliseconds', 'diablocraft-l9s9 (docs/contracts/big-life-messages.md): the batch window of the DCBIGLIFE pushes. A B record (a big creature''s true max Life) and an H record (a hit of 2^32 or more, exact) wait this long after the first of them is queued so a pack of creatures or a burst of hits shares messages. PLACEHOLDER: the report seeds 250 ms; the designer sets it. 0 sends on the player''s next tick.'),
('combat', 'bovine_bardiche_chance_pct', 100.0, NULL, 'percent', 'diablocraft-4p9j9 (Bovine Bardiche, legendary 055; docs/research/legendary-bead-list.csv order 55): the chance, in percent, that a hit calls the herd of cows, scaled by the hit''s proc coefficient (Proc::Rolls: a hit that states none never calls one). d3planner''s text says only ''Chance on hit'' and gives no number; the Power file docs/research/legendary-pow-data.csv ItemPassive_Unique_Ring_520_x1.pow has SF_3 Proc Chance = 1 (100%, gated by its 60 s internal cooldown, the decoder''s reading: docs/research/legendary-pow-decoder.md row 35), the number. The designer''s ruling, docs/decisions.md:1077 (2026-10-14, card q-1014-13 (a)): ''Bovine Bardiche follows the power file, 100% on hit once per 60 s'', so the herd comes on every hit that is off its bovine_bardiche_cooldown_seconds. Blank reads 0: the power does nothing. 0 never, 100 always at a proc coefficient of 1; set at run time with `.dc tunables set combat bovine_bardiche_chance_pct <n>`'),
('combat', 'bovine_bardiche_cooldown_seconds', 60.0, NULL, 'seconds', 'diablocraft-4p9j9 (Bovine Bardiche): the internal cooldown after a herd comes, docs/research/legendary-pow-data.csv ItemPassive_Unique_Ring_520_x1.pow SF_1 Internal Cooldown = 60. A hit that did not call a herd starts nothing; 0 no cooldown'),
('combat', 'bovine_bardiche_cow_damage_delta_pct', 200.0, NULL, 'percent', 'diablocraft-4p9j9 (Bovine Bardiche): the spread above bovine_bardiche_cow_damage_pct, so one attack is 400-600% of weapon damage, docs/research/legendary-pow-data.csv ItemPassive_Unique_Ring_520_x1.pow SF_5 Cow Weapon Damage % Delta = 2 (x100)'),
('combat', 'bovine_bardiche_cow_damage_pct', 400.0, NULL, 'percent', 'diablocraft-4p9j9 (Bovine Bardiche): the low end of one cow attack, in percent of weapon damage, docs/research/legendary-pow-data.csv ItemPassive_Unique_Ring_520_x1.pow SF_4 Cow Weapon Damage % = 4 (x100, as the Power files'' weapon damage scalars: legendary-pow-decoder.md row 35 ''cow damage 4 (+2 delta) x weapon damage''). A cow attacks at its owner''s attacks per second, as the Ancients do (dc_item_summons.cpp)'),
('combat', 'bovine_bardiche_cow_life_pct_of_owner', NULL, NULL, 'percent', 'diablocraft-4p9j9 (Bovine Bardiche): each cow''s Life, in percent of the owner''s maximum Life (the Ancients'' ancients_life_pct_of_owner shape). No Power file number. The designer''s ruling, docs/decisions.md:1077 (2026-10-14, card q-1014-13 (a)): the cow''s Life is ''a stock cow summon''s at the player''s level'', so blank (the shipped value) gives each cow the stock Cow 2442''s Life for the owner''s level (creature_classlevelstats of that level and the Cow''s class, times its Health modifier); a number here overrides it with that share of the owner''s maximum Life'),
('combat', 'bovine_bardiche_cow_seconds', 15.0, NULL, 'seconds', 'diablocraft-4p9j9 (Bovine Bardiche): how long each cow of a herd stays (the summon''s own timer), docs/research/legendary-pow-data.csv ItemPassive_Unique_Ring_520_x1.pow SF_2 Cow Duration = 15. 0 calls no cow'),
('combat', 'buff_values_push_ms', NULL, 250.0, 'milliseconds', 'diablocraft-xumo (buff icons build 1): the least time between two records the server sends the addon for one buff''s values (docs/contracts/buff-values-messages.md): Gogok changes on every hit, so its Dodge line is sent at most this often, the latest value always. No D3 number and none in the brief beyond ''a few a second''. PLACEHOLDER: 250 is an engineering figure; the designer sets it. 0 sends every change.'),
('combat', 'bul_kathos_drain_max_heal_pct', 1.0, NULL, 'percent', 'diablocraft-942kn (Bul-Kathos''s Wedding Band): the most one pulse heals, in percent of the player''s maximum Life, docs/research/legendary-pow-data.csv ItemPassive_Unique_Ring_020_x1.pow SF_3 ''max drain HP per pulse'' = 0.01 (x100). 0 heals nothing'),
('combat', 'bul_kathos_drain_max_weapon_damage', 20.0, NULL, 'multiplier', 'diablocraft-942kn (Bul-Kathos''s Wedding Band): the most one pulse takes from one enemy, in multiples of the main hand''s average weapon damage (template, gem and rolled elemental range, plus the sheet''s flat weapon damage), docs/research/legendary-pow-data.csv ItemPassive_Unique_Ring_020_x1.pow SF_1 ''Max X Weapon Damage Per Target'' = 20. 0 drains nothing'),
('combat', 'bul_kathos_drain_radius_yards', 8.0, NULL, 'yards', 'diablocraft-942kn (Bul-Kathos''s Wedding Band, legendary 056; docs/research/legendary-bead-list.csv order 56): how far around the player each drain pulse reaches, docs/research/legendary-pow-data.csv ItemPassive_Unique_Ring_020_x1.pow SF_5 ''damage area'' = 8. 0 drains nothing'),
('combat', 'class_buff_refresh_ms', NULL, 250.0, 'milliseconds', 'diablocraft-b3zj (buff icons build 2): how often the module looks at the conditions of the Barbarian''s passive buffs (Relentless''s Life, Berserker Rage''s Fury, Brawler''s enemy count within its radius) to put the buff on or take it off. No D3 number. PLACEHOLDER: 250 is an engineering figure; the designer sets it. A smaller step answers sooner and costs more grid searches (Brawler counts the enemies around). The Wizard''s buffs follow its own 250 ms upkeep.'),
('combat', 'corpse_cap', NULL, 30.0, 'count', 'How many corpses one player keeps at a time (Necromancer 2c, diablocraft-im7mr.7); past it the oldest goes. No local file or the D3 power files give a cap (docs/research/necromancer/README.md ''Corpses'', G2 question 4); the designer''s answer on card q-1021-35 (a) is 30 (2026-10-22)'),
('combat', 'corpse_lifetime_seconds', NULL, 60.0, 'seconds', 'How long a corpse lies before it is gone (Necromancer 2c, diablocraft-im7mr.7). No local file or the D3 power files give it (docs/research/necromancer/README.md ''Corpses'', G2 question 4); the designer''s answer on card q-1021-35 (a) is 60 seconds (2026-10-22)'),
('combat', 'dual_wield_ias_pct', 15.0, NULL, 'percent', 'from stats.csv:stat=Attack Speed.dual_wield_ias_pct, stats.csv Attack Speed how_it_stacks: ''Dual-wielding adds an additive 15% IAS into the sheet bucket''; formula_for_effect DualWield_15%'),
('combat', 'fire_walkers_patch_seconds', 1.5, NULL, 'seconds', 'Fire Walkers (legendary 058, N-AREA, diablocraft-4na3e): how long a dropped fire patch burns, the Power file read with decode_pow.py (power ItemPassive_Unique_Boots_007_p2, reference/blizzless-diiis 6292f950) SF_4 ''Proxy duration'' = 1.5. 0 drops no patch'),
('combat', 'fire_walkers_radius_yards', 5.0, NULL, 'yards', 'Fire Walkers (legendary 058, N-AREA, diablocraft-4na3e): how far from a live fire patch an enemy still burns, docs/research/legendary-bead-list.csv order 58; the Power file read with decode_pow.py (power ItemPassive_Unique_Boots_007_p2, reference/blizzless-diiis 6292f950) SF_5 ''Damage radius'' = 5. 0 burns nothing'),
('combat', 'gem_aura_refresh_ms', NULL, 500.0, 'milliseconds', 'diablocraft-apkq (legendary gems 10b-4): how often the module looks at the enemies around a gem wearer and at the wearer''s own condition: Bane of the Trapped''s slow aura (refreshed this often, lasting twice as long), Pain Enhancer''s Blood Frenzy (bleeding enemies counted this often), Esoteric Alteration''s below-half-Life check and the stacks that lapse. No D3 or d3planner number (the gem texts say only that the effect follows the enemies and the Life). PLACEHOLDER: 500 is the engineering figure 10b-4 ships; the designer sets it. A smaller step answers sooner and costs more grid searches.'),
('combat', 'gem_iceblink_chill_seconds', NULL, NULL, 'seconds', 'diablocraft-y75r (legendary gems 10b-3): how long the Chill that Iceblink''s Cold skills apply lasts; the gem''s text states no duration (each Wizard rune and Barbarian rune states its own). Blank = no duration chosen, so Iceblink applies no Chill until the designer sets it.'),
('combat', 'gem_iceblink_chill_slow_pct', 60.0, NULL, 'percent', 'diablocraft-y75r (legendary gems 10b-3): the movement slow of the Chill Iceblink''s Cold skills apply, before the gem''s own additional slow. 60 is the same published figure the Wizard''s wizard_chill_slow_pct and the Barbarian chill rows use (maxroll Crowd Control Explained, adopted by ruling 2026-09-29: the current unstated D3 chill slow is 60%).'),
('combat', 'gem_mirinae_smite_range_yards', NULL, NULL, 'yards', 'diablocraft-y75r (legendary gems 10b-3): how far "a nearby enemy" is for Mirinae''s smite, measured from the player; neither the sheet nor d3planner gives a distance. Blank = no distance chosen, so the smite does not fire (the heal with it neither) until the designer sets it.'),
('combat', 'gem_moratorium_pay_period_ms', NULL, 250.0, 'milliseconds', 'diablocraft-5rv0 (return of y75r): how often Moratorium pays the damage it put off, as one combat-log line per step; a smaller step is a smoother bar and more lines. No D3 or d3planner number (the gem text says only that the damage is taken over time). PLACEHOLDER: 250 is the engineering figure y75r shipped; the designer sets it. The generator bakes it into Spell.dbc record 83404 (EffectAuraPeriod_1) and the module reads it back off that record, so changing it needs generate_spells.py and a client patch, not .dc tunables set.'),
('combat', 'gem_wreath_radius_yards', NULL, NULL, 'yards', 'diablocraft-y75r (legendary gems 10b-3): the radius of "nearby enemies" for Wreath of Lightning''s pulse, from the player; neither the sheet nor d3planner gives one. Blank = no radius chosen, so the Wreath is gained but its pulses hit nothing until the designer sets it.'),
('combat', 'globe_display_id', NULL, 8365.0, 'count', 'Health globes G2 (diablocraft-vul07.4): the gameobject display the health globe wears. The designer picked 8365, the Blood Orb (red, on its pedestal, drawn as the client has it), from the .dc orbrow row on dev (2026-10-16, diablocraft-ivtf5). Nothing reads it yet: G2 builds the globe object from it, as generate_rifts.py builds the progress orb from rifts gr_orb_display_id. The Nephalem Globe and Nephalem Glory get no pick (stxs8)'),
('combat', 'ground_device_look_seconds', 0.25, NULL, 'seconds', 'Ground devices (the shared placed-device piece): the seconds between the looks of an armed device that fires when an enemy comes within reach, for an enemy there (the designer''s standing default, AGENTS.md Numbers: a trigger check runs every 0.25 s; the power files give none)'),
('combat', 'ground_marker_radius_yards', NULL, 2.0, 'yards', 'diablocraft-ground-target-circles (ruling q-0930-09 "size them per skill"); the green ground cursor of a skill with no area (Teleport and its runes and Archon Teleport; Furious Charge''s target point); baked into client Spell.dbc so a change needs a client patch rebuild and release; must be a stock SpellRadius yardage (0.5 1 2 3 3.5 4 5 6 7 8 9 10 ...); worker''s starting value - the designer sets it'),
('combat', 'minion_timer_net_seconds', 1.0, NULL, 'seconds', 'Timed minions (the shared minions piece): how far the core''s own timer on a timed minion runs behind the AI''s, so the AI sees the end first and can act on it (not D3: kept from the build; an engine margin, not a game number)'),
('combat', 'passive_skill_slots', 4.0, NULL, 'count', 'from character_rules.csv:name=passive_skill_slots.value, Blizzard Game Guide quoted verbatim on the official Blizzard forums https://eu.forums.blizzard.com/en/d3/t/is-there-any-way-to-get-more-than-four-passive-skills/4446 post 5 - "That''s four in total."; corroborated by Diablo Wiki https://diablo.fandom.com/wiki/Passive_skill_(Diablo_III). Sourced by Gemini, docs/research/literal-audit-sources-2.md row 23'),
('combat', 'passive_slot_1_unlock_level', 10.0, NULL, 'level', 'from character_rules.csv:name=passive_slot_1_unlock_level.value, Blizzard Game Guide quoted verbatim on the official Blizzard forums https://eu.forums.blizzard.com/en/d3/t/is-there-any-way-to-get-more-than-four-passive-skills/4446 post 5 - "As you reach levels 10, 20 and 30 (and 70 with Reaper of Souls), you''ll unlock a passive skill slot."; corroborated by Diablo Wiki https://diablo.fandom.com/wiki/Passive_skill_(Diablo_III). Sourced by Gemini, docs/research/literal-audit-sources-2.md row 18'),
('combat', 'passive_slot_2_unlock_level', 20.0, NULL, 'level', 'from character_rules.csv:name=passive_slot_2_unlock_level.value, Blizzard Game Guide quoted verbatim on the official Blizzard forums https://eu.forums.blizzard.com/en/d3/t/is-there-any-way-to-get-more-than-four-passive-skills/4446 post 5 - "As you reach levels 10, 20 and 30 (and 70 with Reaper of Souls), you''ll unlock a passive skill slot.". Sourced by Gemini, docs/research/literal-audit-sources-2.md row 19'),
('combat', 'passive_slot_3_unlock_level', 30.0, NULL, 'level', 'from character_rules.csv:name=passive_slot_3_unlock_level.value, Blizzard Game Guide quoted verbatim on the official Blizzard forums https://eu.forums.blizzard.com/en/d3/t/is-there-any-way-to-get-more-than-four-passive-skills/4446 post 5 - "As you reach levels 10, 20 and 30 (and 70 with Reaper of Souls), you''ll unlock a passive skill slot.". Sourced by Gemini, docs/research/literal-audit-sources-2.md row 20'),
('combat', 'passive_slot_4_unlock_level', 70.0, NULL, 'level', 'from character_rules.csv:name=passive_slot_4_unlock_level.value, Blizzard Game Guide quoted verbatim on the official Blizzard forums https://eu.forums.blizzard.com/en/d3/t/is-there-any-way-to-get-more-than-four-passive-skills/4446 post 5 - "As you reach levels 10, 20 and 30 (and 70 with Reaper of Souls), you''ll unlock a passive skill slot."; the fourth slot is the Reaper of Souls one. Sourced by Gemini, docs/research/literal-audit-sources-2.md row 21'),
('combat', 'passive_slot_gap_ms', NULL, 150.0, 'milliseconds', 'security.md G1 gaps; brief docs/briefs/claude-combat-g1-gaps-brief.md (ruling 2026-09-30) says start around 100-250; least time between two DCPASSIVE passive changes from one player - each waits for a database commit; 0 disables it'),
('combat', 'pylon_channeling_cooldown_reduction_pct', 75.0, NULL, 'percent', 'Channeling Pylon (docs/proposals/pylons.md 4.3): cooldowns of skills cast during the buff are this much shorter (a Temporary sheet contribution, the class''s own cooldown aura rebuilt). D3: 75% (Fandom, Icy Veins, in-game text). The effect reads this live (.dc tunables set moves it); the buff''s tooltip text is baked from it by generate_spells.py (pylons.md, data/pylon_buffs.csv), so a changed number also needs the generator and a client patch to show the new text.'),
('combat', 'pylon_channeling_cost_reduction_pct', 100.0, NULL, 'percent', 'Channeling Pylon (docs/proposals/pylons.md 4.3): resource costs are this much lower; 100 removes them, as D3''s "all resource costs are removed" (Icy Veins: not the skills that drain all resource). A Temporary sheet contribution. The effect reads this live (.dc tunables set moves it); the buff''s tooltip text is baked from it by generate_spells.py (pylons.md, data/pylon_buffs.csv), so a changed number also needs the generator and a client patch to show the new text.'),
('combat', 'pylon_channeling_display_id', NULL, 363.0, 'count', 'Pylons and shrines P3 (diablocraft-7h5tr; docs/proposals/pylons.md 6.7 (b)): the gameobject display the Channeling Pylon''s object wears. PLACEHOLDER: a stock WoW object the designer picks on dev with .dc pylon spawn <kind> (no Blizzard art, 2026-10-05); it starts at the progress orb''s stock look (363, rifts gr_orb_display_id) as 6.7 says. Read by generate_pylon_objects.py into combat_0054_pylon_objects.sql, so a change needs the generator rerun and that migration applied, not a .dc tunables set'),
('combat', 'pylon_channeling_seconds', 30.0, NULL, 'seconds', 'Channeling Pylon (docs/proposals/pylons.md 6.3): how long the buff lasts. D3: 30 s (Fandom, Icy Veins).'),
('combat', 'pylon_conduit_boss_factor', NULL, 1.0, 'multiplier', 'Pylons and shrines P2 (diablocraft-eok78; docs/proposals/pylons.md 6.10): a Rift Guardian or a boss takes a strike times this. PLACEHOLDER: D3 2.3.0 ''Conduit now deals reduced damage to bosses and Rift Guardians'', by how much not published; 1 (no cut) is 6.10''s start until the designer sets one. Read live (.dc tunables set moves it).'),
('combat', 'pylon_conduit_display_id', NULL, 363.0, 'count', 'Pylons and shrines P3 (diablocraft-7h5tr; docs/proposals/pylons.md 6.7 (b)): the gameobject display the Conduit Pylon''s object wears. PLACEHOLDER: a stock WoW object the designer picks on dev with .dc pylon spawn <kind> (no Blizzard art, 2026-10-05); it starts at the progress orb''s stock look (363, rifts gr_orb_display_id) as 6.7 says. Read by generate_pylon_objects.py into combat_0054_pylon_objects.sql, so a change needs the generator rerun and that migration applied, not a .dc tunables set'),
('combat', 'pylon_conduit_greater_life_max_pct', 50.0, NULL, 'percent', 'Pylons and shrines P2 (diablocraft-eok78; docs/proposals/pylons.md 6.10 (a)): the top of the Greater Rift strike''s share (see pylon_conduit_greater_life_min_pct). D3: Max 0.5 in the same measurement. Read live (.dc tunables set moves it).'),
('combat', 'pylon_conduit_greater_life_min_pct', 40.0, NULL, 'percent', 'Pylons and shrines P2 (diablocraft-eok78; docs/proposals/pylons.md 6.10 (a)): in a Greater Rift a strike takes a share of the Life the struck monster has as a normal monster at the run''s level (its Life without the elite Life factor), whatever the gear; the share is rolled between this row and pylon_conduit_greater_life_max_pct. D3: ''610248.7×(Min:0.4 - Max:0.5)×GR Life Multiplier'' (a player''s measurement, Reddit zbyxzh 2016-04-25; 610,248.7 is D3''s level-70 monster base Life, diiis-catalogue.md:341). Read live (.dc tunables set moves it).'),
('combat', 'pylon_conduit_pulse_ms', NULL, 1000.0, 'milliseconds', 'Pylons and shrines P2 (diablocraft-eok78; docs/proposals/pylons.md 6.10): how often the Conduit buff strikes. PLACEHOLDER: D3 publishes no pulse; 1000 (a pulse a second) is 6.10''s start, which with 5 targets makes the low end of the guides'' ''5-10 times per second'' in a packed room. The designer sets it. Baked into the buff record''s period by generate_spells.py, so a change needs the generator, the spell migration and a client patch, not a .dc tunables set.'),
('combat', 'pylon_conduit_radius_yards', NULL, 50.0, 'yards', 'Pylons and shrines P2 (diablocraft-eok78; docs/proposals/pylons.md 6.10): a pulse strikes monsters within this distance of the wearer. PLACEHOLDER: D3 says ''your surroundings'' and publishes no radius; 50 is 6.10''s start, the screen edge of 6.4. The designer sets it. Read live (.dc tunables set moves it).'),
('combat', 'pylon_conduit_rehit_seconds', 2.0, NULL, 'seconds', 'Pylons and shrines P2 (diablocraft-eok78; docs/proposals/pylons.md 6.10): one player''s Conduit strikes a monster at most once in this many seconds. D3: ''only delivers one hit every 2 seconds to each'' (Fandom, Shrines (Diablo III), revision 242183). Read live (.dc tunables set moves it).'),
('combat', 'pylon_conduit_seconds', 30.0, NULL, 'seconds', 'Conduit Pylon (docs/proposals/pylons.md 6.3): how long the buff lasts. D3: 30 s in both rift kinds since patch 2.3.0 (15 s in a Greater Rift from 2.1.0 to 2.3.0). Part P2 builds the strikes.'),
('combat', 'pylon_conduit_targets', NULL, 5.0, 'count', 'Pylons and shrines P2 (diablocraft-eok78; docs/proposals/pylons.md 6.10): at most this many monsters a pulse strikes. PLACEHOLDER: D3 limits the targets (2.1.2, fewer per pulse in 2.4.0) and publishes no count; 5 is 6.10''s start. The designer sets it. Read live (.dc tunables set moves it).'),
('combat', 'pylon_conduit_weapon_damage_pct', 4000.0, NULL, 'percent', 'Pylons and shrines P2 (diablocraft-eok78; docs/proposals/pylons.md 6.10 (a)): outside a Greater Rift a strike is a hit of this much weapon damage as Lightning through the damage formula, with the wearer''s crits and the sheet''s multipliers. D3: ''roughly 4000% damage as Lightning, has access to the hero''s full assortment of critical hit stats'' (Fandom, revision 242183); Maxroll: ''scales with your generic damage multipliers''. Read live (.dc tunables set moves it).'),
('combat', 'pylon_list_burst', NULL, 5.0, 'count', 'Pylons and shrines P3 (diablocraft-7h5tr; docs/contracts/pylon-messages.md): DCPYLON list requests (the addon asks for the standing pylons and shrines of its map after a /reload) a player may send at once. PLACEHOLDER: the same start as big_life_pull_burst; the addon asks once per /reload. The designer sets it. Blank would mean the route refuses every request (docs/contracts/window-bridge.md, Budget).'),
('combat', 'pylon_list_per_second', NULL, 1.0, 'count', 'Pylons and shrines P3 (diablocraft-7h5tr; docs/contracts/pylon-messages.md): DCPYLON list tokens per second a player gets back. PLACEHOLDER: the same start as big_life_pull_per_second. The designer sets it. Blank would mean the route refuses every request (docs/contracts/window-bridge.md, Budget).'),
('combat', 'pylon_power_damage_pct', 400.0, NULL, 'percent', 'Power Pylon (docs/proposals/pylons.md 4.3, 6.3): damage dealt, a separate multiplier of its own (x5) in step 8 of the hit. D3: +400% (the in-game text, Blizzard''s guide, Fandom, Icy Veins); Maxroll and one 2023 player say +250%, not taken (6.3). The effect reads this live (.dc tunables set moves it); the buff''s tooltip text is baked from it by generate_spells.py (pylons.md, data/pylon_buffs.csv), so a changed number also needs the generator and a client patch to show the new text.'),
('combat', 'pylon_power_display_id', NULL, 363.0, 'count', 'Pylons and shrines P3 (diablocraft-7h5tr; docs/proposals/pylons.md 6.7 (b)): the gameobject display the Power Pylon''s object wears. PLACEHOLDER: a stock WoW object the designer picks on dev with .dc pylon spawn <kind> (no Blizzard art, 2026-10-05); it starts at the progress orb''s stock look (363, rifts gr_orb_display_id) as 6.7 says. Read by generate_pylon_objects.py into combat_0054_pylon_objects.sql, so a change needs the generator rerun and that migration applied, not a .dc tunables set'),
('combat', 'pylon_power_seconds', 30.0, NULL, 'seconds', 'Power Pylon (docs/proposals/pylons.md 6.3): how long the buff lasts. D3: 30 s (in-game text, Blizzard''s guide, Icy Veins).'),
('combat', 'pylon_shield_display_id', NULL, 363.0, 'count', 'Pylons and shrines P3 (diablocraft-7h5tr; docs/proposals/pylons.md 6.7 (b)): the gameobject display the Shield Pylon''s object wears. PLACEHOLDER: a stock WoW object the designer picks on dev with .dc pylon spawn <kind> (no Blizzard art, 2026-10-05); it starts at the progress orb''s stock look (363, rifts gr_orb_display_id) as 6.7 says. Read by generate_pylon_objects.py into combat_0054_pylon_objects.sql, so a change needs the generator rerun and that migration applied, not a .dc tunables set'),
