('crafting', 'starter_wrists_count', NULL, 1.0, 'count', 'Codex CSV inventory starter_kit.csv wrists/count; 08-world W6 and the designer starter-kit policy; rarity remains metadata.'),
('crusader', 'akarats_champion_fire_starter_icd_factor', 0.9, NULL, 'multiplier', 'Akarat''s Champion - Fire Starter: the gap before the same enemy burns again is this over the Crusader''s attacks a second (Power/X1_Crusader_AkaratsChampion.pow SF_40 ''A: DoT Application ICD'' = 0.9 / Attacks_Per_Second_Total)'),
('crusader', 'akarats_champion_fire_starter_tick_seconds', NULL, 0.5, 'seconds', 'Akarat''s Champion - Fire Starter: the interval between the ticks of the burn (the sheet''s 460% weapon damage over 3 seconds): 6 ticks of 460/6 percent. The sheet and Power/X1_Crusader_AkaratsChampion.pow state no tick length (SF_6 ''Fire Damage Tick-Interval'' = 0.2 belongs to the fire pools of the rune''s earlier form); the d3planner Crusader simulator ticks the burn six times over the 3 seconds (card q-1021-29, closed from that source)'),
('crusader', 'blessed_hammer_arc_chance_pct', 30.0, NULL, 'percent', 'Blessed Hammer - Thunderstruck: the chance, at each look, of an arc between the Crusader and the hammer (''occasionally''). Power/X1_Crusader_BlessedHammer.pow SF_33 ''B: Lightning Chance'' = 0.3'),
('crusader', 'blessed_hammer_hit_radius_yards', NULL, 5.0, 'yards', 'Blessed Hammer: how near the hammer must be to an enemy to hit it, and how wide Thunderstruck''s arcs are. The hammer''s size is in no source (the sheet, the power file''s formulas); the designer answered 5 yards (card q-1021-13)'),
('crusader', 'blessed_hammer_limitless_life_factor', 1.5, NULL, 'multiplier', 'Blessed Hammer - Limitless: how much longer the hammer lasts with the rune. Power/X1_Crusader_BlessedHammer.pow SF_38 ''C: Increased Lifetime'' = 1.5; the sheet states only the larger area'),
('crusader', 'blessed_hammer_loops', NULL, 1.5, 'count', 'Blessed Hammer: how many times round the Crusader the hammer goes over its life, in loops. The designer answered about 1.5 (card q-1021-10), a number he tunes in game'),
('crusader', 'blessed_hammer_pool_radius_yards', 8.0, NULL, 'yards', 'Blessed Hammer - Burning Wrath: how far from the middle of a fire pool an enemy still burns. Power/X1_Crusader_BlessedHammer.pow SF_7 ''A: Fire Pool Target Radius'' = 8'),
('crusader', 'blessed_hammer_pool_seconds', 2.0, NULL, 'seconds', 'Blessed Hammer - Burning Wrath: how long a fire pool burns. Power/X1_Crusader_BlessedHammer.pow SF_13 ''A: Pool Duration'' = 2'),
('crusader', 'blessed_hammer_pool_tick_seconds', 1.0, NULL, 'seconds', 'Blessed Hammer - Burning Wrath: the interval between a pool''s ticks. The sheet says the pool deals its damage ''per second'''),
('crusader', 'blessed_hammer_pools_at_once', 4.0, NULL, 'count', 'Blessed Hammer - Burning Wrath: the most pools one Crusader has burning at a time. Power/X1_Crusader_BlessedHammer.pow SF_14 ''A: Max # Pools at a time'' = 4'),
('crusader', 'blessed_hammer_reach_yards', NULL, 15.0, 'yards', 'Blessed Hammer: how far from the Crusader the hammer''s spiral ends, the radius it grows to over its life. The designer answered 15 yards (card q-1021-10), a number he tunes in game'),
('crusader', 'blessed_hammer_seconds', NULL, 3.0, 'seconds', 'Blessed Hammer: how long the hammer spins before it is gone. The sheet says it spins around you and no source states its life; the designer answered 3 seconds (card q-1021-10), a number he tunes in game'),
('crusader', 'blessed_hammer_slow_pct', NULL, 60.0, 'percent', 'Blessed Hammer - Brute Force: how much the hammer slows the enemies it hits. The sheet says ''Slows enemies it passes through'' and gives no percentage; the designer answered 60% for 2 seconds (card q-1021-11)'),
('crusader', 'blessed_hammer_slow_seconds', NULL, 2.0, 'seconds', 'Blessed Hammer - Brute Force: how long that slow lasts. No source states it; the designer answered 2 seconds (card q-1021-11)'),
('crusader', 'blessed_hammer_step_seconds', 0.1, NULL, 'seconds', 'Blessed Hammer: how often the module looks where the hammer is and whom it touches, and how often Thunderstruck may arc. Power/X1_Crusader_BlessedHammer.pow SF_16 ''B: Tickrate'' = 0.1'),
('crusader', 'blessed_shield_bounce_yards', 20.0, NULL, 'yards', 'Blessed Shield: how far from the enemy it hit the shield looks for the next enemy to ricochet to, and where Shattering Throw''s fragments find theirs. Power/X1_Crusader_BlessedShield.pow SF_13 ''Target Bounce Radius'' = 20, skill_targeting.csv'),
('crusader', 'blessed_shield_knockaside_yards', NULL, 3.0, 'yards', 'Blessed Shield - Piercing Shield: how far an enemy it knocks aside is moved (away from the Crusader). The sheet says ''knock them aside''; the power file has a magnitude of 10 (SF_25) in no unit the module uses; the designer answered 3 yards (card q-1021-16)'),
('crusader', 'blessed_shield_pierce_width_yards', NULL, 3.0, 'yards', 'Blessed Shield - Piercing Shield: how wide the line is along which the shield pierces enemies. The sheet says it ''pierces through all enemies'' and the power file''s formulas give no width; the designer answered 3 yards (card q-1021-15)'),
('crusader', 'blessed_shield_range_yards', 70.0, NULL, 'yards', 'Blessed Shield - Piercing Shield: how far down its line the shield pierces. Power/X1_Crusader_BlessedShield.pow SF_0 ''Max Range'' = 70, skill_targeting.csv'),
('crusader', 'bombardment_barrels_wait_added_seconds', 0.1, NULL, 'seconds', 'Bombardment - Barrels of Spikes: what the rune adds to the least wait (Power/X1_Crusader_Bombardment.pow SF_18 ''A: Spawn Rate Modifier Min'' = 0.1)'),
('crusader', 'bombardment_first_delay_seconds', 0.35, NULL, 'seconds', 'Bombardment: the wait before the first sphere leaves (Power/X1_Crusader_Bombardment.pow SF_4 ''Spawn Rate Delay'' = 0.35)'),
('crusader', 'bombardment_impact_delay_seconds', 0.55, NULL, 'seconds', 'Bombardment: how long a sphere takes from leaving to its impact (Power/X1_Crusader_Bombardment.pow SF_14 ''Impact Delay'' = 0.55)'),
('crusader', 'bombardment_mine_check_seconds', NULL, 0.25, 'seconds', 'Bombardment - Mine Field: how often the module looks at whether an enemy has walked near a mine. D3 checks every frame and no D3 source holds an interval; the standing default for a check with no sourced number is 0.25 seconds (card q-1021-32 closed by it). The code never looks more often than every 0.1 seconds (dc_crusader_bombardment.cpp MineCheckFloorSeconds); a shorter interval catches a fast enemy sooner and costs more'),
('crusader', 'bombardment_mine_field_wait_added_seconds', 0.5, NULL, 'seconds', 'Bombardment - Mine Field: what the rune adds to the least wait (Power/X1_Crusader_Bombardment.pow SF_30 ''C: Spawn Rate Modifier Min'' = 0.5)'),
('crusader', 'bombardment_mine_max_yards', 30.0, NULL, 'yards', 'Bombardment - Mine Field: the farthest from its impact a mine lies (Power/X1_Crusader_Bombardment.pow SF_28 ''C: Max Mine Spawn Distance'' = 30)'),
('crusader', 'bombardment_mine_min_yards', 5.0, NULL, 'yards', 'Bombardment - Mine Field: the nearest to its impact a mine lies (Power/X1_Crusader_Bombardment.pow SF_29 ''C: Min Mine Spawn Distance'' = 5)'),
('crusader', 'bombardment_mine_seconds', 5.0, NULL, 'seconds', 'Bombardment - Mine Field: how long a mine waits for an enemy (Power/X1_Crusader_Bombardment.pow SF_24 ''C: Mine Lifetime'' = 5)'),
('crusader', 'bombardment_search_radius_yards', 35.0, NULL, 'yards', 'Bombardment: how far from the aimed point the spheres look for the enemy they fall on (Power/X1_Crusader_Bombardment.pow SF_13 ''Search radius'' = 35); the sheet says ''enemies around you'''),
('crusader', 'bombardment_spawn_wait_extra_seconds', 1.5, NULL, 'seconds', 'Bombardment: the most that is added at random to the least wait before the next sphere (Power/X1_Crusader_Bombardment.pow SF_39 ''Base: Spawn Rate Wait Delta Time'' = 1.5)'),
('crusader', 'bombardment_spawn_wait_seconds', 0.55, NULL, 'seconds', 'Bombardment: the least wait before the next sphere leaves (Power/X1_Crusader_Bombardment.pow SF_7 ''Base: Spawn Rate Wait Min Time'' = 0.55)'),
('crusader', 'condemn_vacuum_interval_seconds', 0.5, NULL, 'seconds', 'Condemn - Vacuum: how often it sucks enemies in while the explosion builds (Power/X1_Crusader_Condemn.pow SF_11 ''B: Suck in interval'' = 0.5); the pulses that fit the build time, the first one an interval in'),
('crusader', 'condemn_vacuum_max_targets', 10.0, NULL, 'count', 'Condemn - Vacuum: the most enemies one pulse draws in, the nearest first (Power/X1_Crusader_Condemn.pow SF_18 ''B: Max #Targets sucked in'' = 10)'),
('crusader', 'condemn_vacuum_offset_extra_yards', 1.0, NULL, 'yards', 'Condemn - Vacuum: the most added at random to the nearest distance an enemy is drawn to (Power/X1_Crusader_Condemn.pow SF_20 ''B: knockback offset DELTA'' = 1)'),
('crusader', 'condemn_vacuum_offset_min_yards', 2.0, NULL, 'yards', 'Condemn - Vacuum: the nearest an enemy is drawn to the Crusader (Power/X1_Crusader_Condemn.pow SF_19 ''B: knockback offset MIN'' = 2); the draw sets it down that far from the Crusader plus a random part of the extra below'),
('crusader', 'condemn_vacuum_radius_step_yards', 2.5, NULL, 'yards', 'Condemn - Vacuum: how much farther each pulse reaches than the one before it, from the explosion''s own radius (Power/X1_Crusader_Condemn.pow SF_17 ''B: Target Radius Add Each Time'' = 2.5, SF_16 ''Target Radius Start'' = the explosion radius). The first pulse reaches the radius plus one step, because it takes only enemies beyond the explosion (SF_21 ''Min Distance to Suck in'' = the explosion radius): a first pulse at the radius alone would take none'),
('crusader', 'consecration_barrier_check_seconds', NULL, 0.25, 'seconds', 'Consecration - Aegis Purgatory: how often the module looks at the enemies near the edge to put back one that has crossed it. D3 blocks movement every frame and the sheets state no interval; the designer set 0.25 seconds (q-1021-21). The code never looks more often than every 0.1 seconds (dc_crusader_consecration.cpp CheckFloorSeconds, a guard against 0); a shorter interval lets fewer enemies slip a yard through and costs more'),
('crusader', 'consecration_tick_seconds', 1.0, NULL, 'seconds', 'Consecration: the interval between the ground''s heal and its per-second effects (Bed of Nails, Shattered Ground, Fearful). The sheets say ''Life per second'', ''every second'' and ''per second'', so one second'),
('crusader', 'falling_sword_flurry_radius_yards', 15.0, NULL, 'yards', 'Falling Sword - Flurry: the radius of the flurry, which strikes and incapacitates the enemies in it (Power/X1_Crusader_FallingSword.pow SF_42 ''E: Radius'' = 15)'),
('crusader', 'falling_sword_flurry_tick_seconds', 0.25, NULL, 'seconds', 'Falling Sword - Flurry: how often the swords strike the enemies in the flurry (Power/X1_Crusader_FallingSword.pow SF_43 ''E: Tick Rate'' = 0.25); the sheet''s 230% weapon damage is read as a rate a second, paid in ticks of this length'),
('crusader', 'falling_sword_part_the_clouds_radius_yards', 24.0, NULL, 'yards', 'Falling Sword - Part the Clouds: how far from the landing the storm reaches, and so which enemies it may strike (Power/X1_Crusader_FallingSword.pow SF_22 ''B: radius'' = 24); the sheet says ''the area you land on'''),
('crusader', 'falling_sword_part_the_clouds_strike_seconds', 0.8, NULL, 'seconds', 'Falling Sword - Part the Clouds: how often the storm strikes one random enemy under it (Power/X1_Crusader_FallingSword.pow SF_20 ''B: refresh rate'' = 0.8); the sheet states no interval'),
('crusader', 'falling_sword_superheated_radius_yards', 14.0, NULL, 'yards', 'Falling Sword - Superheated: the radius of the burning ground (Power/X1_Crusader_FallingSword.pow SF_17 ''A: radius'' = 14, the same as the landing''s)'),
('crusader', 'falling_sword_superheated_tick_seconds', 0.3, NULL, 'seconds', 'Falling Sword - Superheated: how often the burning ground strikes the enemies on it (Power/X1_Crusader_FallingSword.pow SF_12 ''A: refresh rate'' = 0.3); the sheet''s 310% weapon damage a second is paid in ticks of this length'),
('crusader', 'fist_bolt_travel_yards', 85.0, NULL, 'yards', 'Fist of the Heavens: how far each of the explosion''s bolts flies. Power/X1_Crusader_FistOfTheHeavens.pow SF_8 ''Total: Projectile Travel Distance'' = 85'),
('crusader', 'fist_bolt_width_yards', NULL, 3.0, 'yards', 'Fist of the Heavens: how wide the lane of a bolt is, and of Retribution''s fist and Fissure''s arcs: an enemy within half of it of the line is struck. The sheet says the bolts pierce and arc outward and no source gives a width; the designer answered 3 yards for all of them (card q-1021-14)'),
('crusader', 'fist_fissure_arc_yards', 6.0, NULL, 'yards', 'Fist of the Heavens - Fissure: how near another fissure must be for lightning to arc between them. Power/X1_Crusader_FistOfTheHeavens.pow SF_32 ''C: Target Radius between tesla'' = 6'),
('crusader', 'fist_fissure_radius_yards', 8.0, NULL, 'yards', 'Fist of the Heavens - Fissure: how far from the fissure an enemy still burns. Power/X1_Crusader_FistOfTheHeavens.pow SF_31 ''C: Target Radius around cloud'' = 8'),
('crusader', 'fist_fissure_tick_seconds', 0.5, NULL, 'seconds', 'Fist of the Heavens - Fissure: the interval between the fissure''s ticks and its arcs. Power/X1_Crusader_FistOfTheHeavens.pow SF_21 ''C: Test/Damage frequency'' = 0.5'),
('crusader', 'fist_knockback_yards', NULL, 5.0, 'yards', 'Fist of the Heavens - Reverberation: how far the shockwave knocks an enemy away. The sheet says ''knocked away''; the power file has a magnitude of 20 (SF_16) in no unit the module uses; the designer answered 5 yards (card q-1021-17)'),
('crusader', 'fist_tempest_tick_seconds', 1.0, NULL, 'seconds', 'Fist of the Heavens - Heaven''s Tempest: the interval between the storm''s ticks. Power/X1_Crusader_FistOfTheHeavens.pow SF_14 ''A: Refresh Interval'' = 1 (the sheet says ''every second'')'),
('crusader', 'heavens_fury_barrier_check_seconds', NULL, 0.25, 'seconds', 'Heaven''s Fury - Thou Shalt Not Pass: how often the module looks at the enemies near the edge of the ground to put back one that has crossed it. D3 blocks movement every frame and no D3 source holds an interval; the standing default for a check with no sourced number is 0.25 seconds (card q-1021-30 closed by it, as Consecration''s Aegis Purgatory). The code never looks more often than every 0.1 seconds (dc_crusader_hold.cpp CheckFloorSeconds); a shorter interval lets fewer enemies slip a yard through and costs more'),
('crusader', 'heavens_fury_fires_distance_yards', 55.0, NULL, 'yards', 'Heaven''s Fury - Fires of Heaven: how far the beam through the Crusader reaches (Power/X1_Crusader_HeavensFury3.pow SF_14 ''E: Max Distance'' = 55)'),
('crusader', 'heavens_fury_fires_radius_yards', 3.0, NULL, 'yards', 'Heaven''s Fury - Fires of Heaven: how far to each side of the beam''s line an enemy is still struck (Power/X1_Crusader_HeavensFury3.pow SF_15 ''E: Beam radius'' = 3)'),
('crusader', 'heavens_fury_split_beam_radius_yards', 4.0, NULL, 'yards', 'Heaven''s Fury - Split Fury: the radius of each of the smaller beams (Power/X1_Crusader_HeavensFury3.pow SF_21 ''C: Radius'' = 4); the sheet gives no radius'),
('crusader', 'heavens_fury_tick_seconds', 1.0, NULL, 'seconds', 'Heaven''s Fury: the interval between the ticks of the ray, of Blessed Ground and of Split Fury''s beams. The power file gives their damage as a rate a second (Power/X1_Crusader_HeavensFury3.pow SF_1 2.85, SF_6 3.1, SF_11 3.3, SF_20 4.61) and no tick length, and the sheets say ''over 6 seconds''; paid in seconds, a reading, as Consecration''s per-second effects are'),
('crusader', 'judgment_penitence_tick_seconds', 1.0, NULL, 'seconds', 'Judgment - Penitence: the interval between the heals (the rune''s tooltip says the Crusader heals for Life per second, for the rune''s seconds): the sheets say ''per second'', so one second'),
('crusader', 'justice_crack_radius_yards', 40.0, NULL, 'yards', 'Justice - Crack: how far around the enemy hit the smaller hammers look for enemies to fly to. The sheet says the hammer cracks into smaller hammers that fly out; Power/X1_Crusader_Justice.pow SF_2 ''B: Target Area Radius'' = 40'),
('crusader', 'justice_holy_bolt_radius_yards', 60.0, NULL, 'yards', 'Justice - Holy Bolt: how far from the Crusader an ally can be and still be healed. The sheet says ''you and your allies''; Power/X1_Crusader_Justice.pow SF_19 ''E: Heal Radius'' = 60'),
('crusader', 'laws_pulse_seconds', NULL, 1.0, 'seconds', 'The Laws (Valor, Justice, Hope): how often a Law''s aura hands its number to the Crusader and the group within its radius. The sheets state each Law''s numbers and a 60 yard reach and no D3 source holds an interval; the standing default for an aura with no sourced number is a pulse every 1 second (card q-1021-27, the value already built, filled as final). A number a pulse gives lasts the pulse and a quarter second more, so a longer interval is a coarser aura and a shorter one costs more sheet updates'),
('crusader', 'phalanx_bowmen_fire_seconds', 0.6, NULL, 'seconds', 'Phalanx - Bowmen: how often each bowman shoots (Power/x1_Crusader_Phalanx3.pow SF_7 ''A: Fire Rate'' = 0.6); each shot deals the sheet''s damage'),
('crusader', 'phalanx_charge_distance_yards', 60.0, NULL, 'yards', 'Phalanx: the farthest the avatars run from the Crusader, however far the target point is (Power/x1_Crusader_Phalanx3.pow SF_1 ''Max Distance'' = 60; skill_targeting.csv range 60)'),
('crusader', 'phalanx_charge_speed_base', 0.4, NULL, 'multiplier', 'Phalanx: the power file''s base speed (Power/x1_Crusader_Phalanx3.pow SF_13 ''Base: Speed'' = 0.4); only its ratio to the runes'' speeds below is used, so Shield Charge runs (0.4 + 0.2) / 0.4 times and Stampede (0.4 + 0.3) / 0.4 times as fast as the plain charge'),
('crusader', 'phalanx_charge_speed_yards_per_second', NULL, 24.0, 'yards per second', 'Phalanx: how fast the avatars run to the target point. The power file gives a speed of 0.4 (SF_13) and no unit; the d3planner Crusader simulator moves them 0.4 yards a frame at 60 frames a second, 24 yards a second (card q-1021-25, closed from that source; the unit is inferred from the simulator''s convention). Shield Charge and Stampede run faster in the ratio of the speeds below'),
('crusader', 'phalanx_shield_bearers_check_seconds', NULL, 0.25, 'seconds', 'Phalanx - Shield Bearers: how often the module looks at the enemies near the place they hold to put back one that has crossed it. D3 blocks movement every frame and no D3 source holds an interval; the standing default for a check with no sourced number is 0.25 seconds (card q-1021-26 closed by it, as Consecration''s Aegis Purgatory). The code never looks more often than every 0.1 seconds (dc_crusader_phalanx.cpp CheckFloorSeconds); a shorter interval lets fewer enemies slip a yard through and costs more'),
('crusader', 'phalanx_shield_bearers_radius_yards', 5.0, NULL, 'yards', 'Phalanx - Shield Bearers: the radius of the place they hold, which no enemy crosses (Power/x1_Crusader_Phalanx3.pow SF_33 ''D: Target Area Radius'' = 5)'),
('crusader', 'phalanx_shield_bearers_seconds', 5.0, NULL, 'seconds', 'Phalanx - Shield Bearers: how long the avatars stand at the target point (Power/x1_Crusader_Phalanx3.pow SF_28 ''D: Duration'' = 5); the sheet states no duration'),
('crusader', 'phalanx_shield_charge_bash_radius_yards', 12.0, NULL, 'yards', 'Phalanx - Shield Charge: the radius of the bash where the avatars arrive (Power/x1_Crusader_Phalanx3.pow SF_21 ''B: Bash Radius'' = 12; SF_22 ''B: Bash Angle'' = 22 degrees is not used: the module strikes the whole circle)'),
('crusader', 'phalanx_shield_charge_speed_bonus', 0.2, NULL, 'multiplier', 'Phalanx - Shield Charge: what its charge adds to the base speed (Power/x1_Crusader_Phalanx3.pow SF_12 ''B: Speed Modifier'' = 0.2)'),
('crusader', 'phalanx_stampede_speed_bonus', 0.3, NULL, 'multiplier', 'Phalanx - Stampede: what its charge adds to the base speed (Power/x1_Crusader_Phalanx3.pow SF_43 ''C: Speed Modifier'' = 0.3)'),
('crusader', 'shield_bash_arc_degrees', 30.0, NULL, 'degrees', 'Shield Bash: the width of the cone along the line to the enemy aimed at, in which the bash hits the other enemies. Power/X1_Crusader_ShieldBash2.pow SF_2 ''Total: Angle'' = 30'),
('crusader', 'shield_bash_area_yards', 17.0, NULL, 'yards', 'Shield Bash: how far the bash reaches (the sheet says ''all nearby foes'' and gives no yards). Power/X1_Crusader_ShieldBash2.pow SF_1 ''Total: Radius'' = 17, skill_targeting.csv'),
('crusader', 'shield_bash_cross_length_yards', NULL, 20.0, 'yards', 'Shield Bash - Shield Cross: how far each of the four additional shields reaches from the Crusader. The sheet and the power file''s formulas state no length; the designer answered 20 yards (card q-1021-05)'),
('crusader', 'shield_bash_cross_width_yards', NULL, 5.0, 'yards', 'Shield Bash - Shield Cross: how wide each additional shield hits. The sheet and the power file''s formulas state no width; the designer answered 5 yards (card q-1021-06)'),
('crusader', 'shield_bash_fragment_extra_degrees', 30.0, NULL, 'degrees', 'Shield Bash - Shattered Shield: how much wider than the bash''s cone the fragments reach. Power/X1_Crusader_ShieldBash2.pow SF_19 ''B: Second Target Angle'' = SF_2 + 30'),
('crusader', 'shield_bash_fragment_extra_yards', 10.0, NULL, 'yards', 'Shield Bash - Shattered Shield: how far past the bash''s reach the fragments hit more enemies. Power/X1_Crusader_ShieldBash2.pow SF_18 ''B: Second Target Radius'' = SF_1 + 10'),
('crusader', 'shield_bash_knockback_yards', NULL, 5.0, 'yards', 'Shield Bash - One on One: how far the other enemies hit are knocked back. The sheet says only ''knocked back''; the power file has a magnitude 24 and a height 3 (SF_32, SF_33) in no unit the module uses; the designer answered 5 yards (card q-1021-07)'),
('crusader', 'shield_bash_pound_arc_degrees', 5.0, NULL, 'degrees', 'Shield Bash - Pound: the cone''s width with the rune (its reach is the sheet''s 8 yards). Power/X1_Crusader_ShieldBash2.pow SF_31 ''D: Target Area Modifier'' = 5'),
('crusader', 'shield_bash_stop_yards', 4.0, NULL, 'yards', 'Shield Bash: how far short of the enemy the charge stops. Power/X1_Crusader_ShieldBash2.pow SF_35 ''Stop At Target Distance'' = 4.0. The charge is a move to that place (as the Monk''s dashes), not a run'),
('crusader', 'shield_glare_arc_degrees', 120.0, NULL, 'degrees', 'Shield Glare: how wide the glare''s cone is. data/d3/skill_targeting.csv for Shield Glare cites Power/X1_Crusader_ShieldGlare.pow ''Beam Damage Cone Radius 30 and Angle 120'' (SF_0, SF_3); the core''s cone for the cast is narrower, so the module blinds the enemies of the rest of this arc as well'),
('crusader', 'slash_carve_arc_degrees', NULL, 120.0, 'degrees', 'Slash - Carve: the arc in front of the Crusader the larger area strikes in. Power/X1_Crusader_Slash.pow gives Carve a capsule with ''D: Depth'' 0 and an offset of 2.5 (SF_11, SF_12) and no angle; the designer answered 120 degrees, the DiIiS reading (card q-1021-02). The plain skill keeps the core''s own 90 degree cone'),
('crusader', 'slash_carve_radius_yards', 8.75, NULL, 'yards', 'Slash - Carve: how far in front the larger area reaches (Power/X1_Crusader_Slash.pow SF_13 ''D: Width'' = 8.75; the skill''s own reach is 6, skill_targeting.csv). The sheet says only ''a larger area''. The core''s cone takes the enemies it takes; the module strikes the enemies of this reach it did not take'),
('crusader', 'slash_guard_seconds', NULL, 3.0, 'seconds', 'Slash - Guard: how long the armor lasts, restarted by every enemy hit. The sheet (crusader_skill_values.csv) states 5% armor for each enemy hit and at most 5 stacks and no length, and Power/X1_Crusader_Slash.pow has none either (SF_15, SF_16); the designer answered 3 seconds, the same as Zeal (card q-1021-01)'),
('crusader', 'smite_shared_fate_check_seconds', NULL, NULL, 'seconds', 'PLACEHOLDER for the designer. Smite - Shared Fate: how often the module looks at the bound enemies to see if a pair has moved apart. D3 checks every frame and the sheets state no interval, so there is no sourced number. Blank: the module looks every 0.05 seconds, the code''s floor against 0 (dc_crusader_smite.cpp CheckFloorSeconds); a longer interval catches a stun later and costs less'),
('crusader', 'smite_shared_fate_seconds', 5.0, NULL, 'seconds', 'Smite - Shared Fate: how long the enemies the chains bound stay bound, so how long moving apart can still stun them. The sheet states the stun and the distance and no length; Power/X1_Crusader_Smite.pow SF_33 ''A: Eligible Duration'' = 5.0'),
('crusader', 'smite_shatter_delay_seconds', 0.5, NULL, 'seconds', 'Smite - Shatter: how long after the chains strike an enemy it explodes. The sheet says only that the chains explode; Power/X1_Crusader_Smite.pow SF_10 ''c: Expiration Delay'' = 0.5. 0 explodes at once'),
('crusader', 'steed_charge_draw_distance_yards', 10.0, NULL, 'yards', 'Steed Charge - Draw and Quarter: the distance at which a bound enemy trails the Crusader (Power/X1_Crusader_SteedCharge.pow SF_33 ''E: Min Distance From Player To Drag'' = 10.0): one farther is drawn in to it each tick, one nearer stays where it is'),
('crusader', 'steed_charge_draw_radius_yards', 15.0, NULL, 'yards', 'Steed Charge - Draw and Quarter: how far from the Crusader an enemy can be and still be bound (Power/X1_Crusader_SteedCharge.pow SF_28 ''E: Herd Radius'' = 15.0); the sheet''s target_count of them, the nearest, are bound at the cast'),
('crusader', 'steed_charge_movement_speed_bonus', 1.5, NULL, 'multiplier', 'Steed Charge: the ride''s movement speed bonus (Power/X1_Crusader_SteedCharge.pow SF_1 ''Movement Speed Bonus'' = 1.5), read as +150% movement speed for the whole ride. The sheets state no speed (the tooltip only says ''ride through enemies unhindered''), so the reading is the power file''s alone'),
('crusader', 'steed_charge_nightmare_pool_radius_yards', 6.0, NULL, 'yards', 'Steed Charge - Nightmare: the radius of each pool of fire the horse leaves (Power/X1_Crusader_SteedCharge.pow SF_23 ''D: Fire Pool Damage Radius'' = 6.0)'),
('crusader', 'steed_charge_nightmare_pool_seconds', 1.4, NULL, 'seconds', 'Steed Charge - Nightmare: how long each pool of fire burns (Power/X1_Crusader_SteedCharge.pow SF_24 ''D: Fire Pool Duration'' = 1.4)'),
('crusader', 'steed_charge_nightmare_pool_spacing_yards', 3.1623, NULL, 'yards', 'Steed Charge - Nightmare: how far the horse goes before it leaves the next pool (Power/X1_Crusader_SteedCharge.pow SF_26 ''D: Fire Pool Required Distance To Drop Next Squared'' = 10, so the square root of 10 yards); the module looks once a ride tick. SF_25 ''Fire Pool Max Num'' = 8 is not needed: a pool lasts 1.4 seconds and a ride tick is 0.25, so at most six burn at once'),
('crusader', 'steed_charge_nightmare_pool_tick_seconds', 0.2, NULL, 'seconds', 'Steed Charge - Nightmare: the interval of a pool''s damage; each tick deals the sheet''s 550% for a second times this (Power/X1_Crusader_SteedCharge.pow SF_21 ''D: Fire Pool Interval'' = 0.2, read as the pool''s tick)'),
('crusader', 'steed_charge_spiked_barding_radius_yards', 6.5, NULL, 'yards', 'Steed Charge - Spiked Barding: how far from the Crusader an enemy is struck as the horse rides through it (Power/X1_Crusader_SteedCharge.pow SF_12 ''A: Damage Capsule Radius'' = 6.5; the capsule''s length SF_7 = 4.5 is not used, the module strikes a circle round the Crusader)'),
('crusader', 'steed_charge_tick_seconds', 0.25, NULL, 'seconds', 'Steed Charge: the interval of the ride''s ticks, and so of the damage of Spiked Barding and Draw and Quarter and of the Life of Rejuvenation, which pays its whole heal in this many ticks (Power/X1_Crusader_SteedCharge.pow SF_5 ''A: Damage Tick Interval'' = 1 / SF_6 ''A: Damage Tick Rate Multiplier'' = 1 / 4). Each tick deals the sheet''s per-second number times this'),
('crusader', 'sweep_attack_arc_degrees', 180.0, NULL, 'degrees', 'Sweep Attack: the width of the half circle in front of the Crusader in which the sweep hits (Power/X1_Crusader_SweepAttack.pow SF_27 ''Base Target Pie Angle'' = 180, skill_targeting.csv row Sweep Attack). The core''s own cone is narrower, so the module strikes the enemies of this arc that the cone did not take'),
('crusader', 'sweep_attack_burn_tick_seconds', NULL, 0.5, 'seconds', 'Sweep Attack - Blazing Sweep: the interval between the ticks of the fire: 4 hits of 30% over the 2 seconds. The sheet gives the total (120% weapon damage) and the 2 seconds and the power file''s formulas no tick length (SF_5, SF_17); the designer answered 0.5 seconds (card q-1021-08)'),
('crusader', 'sweep_attack_pull_yards', 1.0, NULL, 'yards', 'Sweep Attack - Gathering Sweep: how far in front of the Crusader the enemies caught are pulled to. Power/X1_Crusader_SweepAttack.pow SF_25 ''A: knockback offset MIN'' = 1 (SF_18 adds a delta of 1 more, a range the module does not roll: the minimum is built)'),
('demonhunter', 'archery_hatred_tick_seconds', NULL, 0.5, 'seconds', 'Archery - second hand crossbow: the interval between the Hatred shares it pays (''Hatred per Second''). Neither the power file (Power/DemonHunter_Passive_Archery.pow gives only SF_3 ''Bonus Hatred Per Sec'' = 1) nor the tooltip gives a tick; the designer''s standing default for a damage over time, 0.5 seconds (2026-10-22), which the Architect rules a heal over time follows, read the same for a resource regenerated over time'),
('demonhunter', 'bolas_freezing_strike_cone_degrees', 90.0, NULL, 'degrees', 'Bolas - Freezing Strike: the width of the cone ahead of the Demon Hunter, centred on the enemy aimed at, that the extra bolas fly into. Power/DemonHunter_Bolas.pow SF_12 ''B: Target Area Angle'' = 90 (the file gives no unit; read as degrees)'),
('demonhunter', 'bolas_freezing_strike_shot_delay_seconds', 0.1, NULL, 'seconds', 'Bolas - Freezing Strike: how long after the one before each further bola of the volley is shot and so explodes. Power/DemonHunter_Bolas.pow SF_13 ''B: Delay Per Shot'' = 0.1'),
('demonhunter', 'bolas_impact_damage_pct', 0.01, NULL, 'percent', 'Bolas: the weapon damage of the bola itself when it lands, before the explosion that carries the damage. Power/DemonHunter_Bolas.pow SF_10 ''Base: Weapon Damage'' = 0.0001 (a fraction of weapon damage, so 0.01 percent)'),
('demonhunter', 'bolas_travel_yards', 75.0, NULL, 'yards', 'Bolas - Freezing Strike: how far from the Demon Hunter the extra bolas look for enemies to hit. Power/DemonHunter_Bolas.pow SF_3 ''Projectile Max Travel Distance'' = 75 (also the skill''s cast range, skill_targeting.csv)'),
('demonhunter', 'brooding_check_seconds', 0.1, NULL, 'seconds', 'Brooding: the interval between the checks whether the Demon Hunter is moving (Power/DemonHunter_Passive_Brooding.pow SF_4 ''Check Interval for Movement'' = 0.1)'),
('demonhunter', 'caltrops_activation_wait_seconds', 30.0, NULL, 'seconds', 'Caltrops: how long a trap waits for an enemy before it goes away unsprung. Power/DemonHunter_Caltrops.pow SF_9 ''Activation Wait Time'' = 30'),
('demonhunter', 'caltrops_bait_linger_seconds', NULL, 0.5, 'seconds', 'Caltrops - Bait the Trap: how long the critical hit chance lasts after each tick (every caltrops_tick_seconds, 0.25 = SF_1 and the designer''s standing default for a trigger check) finds the Demon Hunter in the area. Neither the power file (Power/DemonHunter_Caltrops.pow gives only SF_28 ''E: Crit Increase'') nor the tooltip gives a linger time. A placeholder for the PM to card: two ticks, so one missed check does not drop it'),
('demonhunter', 'caltrops_max_traps', 5.0, NULL, 'count', 'Caltrops: how many traps stand at once; the oldest give way. Power/DemonHunter_Caltrops.pow SF_10 ''Max Traps'' = 5'),
('demonhunter', 'caltrops_slow_seconds', 0.5, NULL, 'seconds', 'Caltrops: how long each tick''s slow lasts, so that it holds while the enemy stays in the area and lapses soon after it leaves. Power/DemonHunter_Caltrops.pow SF_4 ''slow duration'' = 0.5'),
('demonhunter', 'caltrops_tick_seconds', 0.25, NULL, 'seconds', 'Caltrops: the interval between the sprung trap''s ticks, each of which slows (and, for Jagged Spikes, hurts) the enemies in the area. Power/DemonHunter_Caltrops.pow SF_1 ''Tick-Rate Interval'' = 0.25'),
('demonhunter', 'chakram_cloud_cooldown_seconds', 10.0, NULL, 'seconds', 'Chakram - Shuriken Cloud: the rune''s cooldown (the skill and its other runes have none). Power/DemonHunter_Chakram.pow SF_8 ''E: Cooldown'' = 10, CooldownTime = Rune_E ? SF_8 : 0'),
('demonhunter', 'chakram_cloud_radius_yards', 8.0, NULL, 'yards', 'Chakram - Shuriken Cloud: how far from the Demon Hunter the cloud reaches. Power/DemonHunter_Chakram.pow SF_15 ''E: Area'' = 8'),
('demonhunter', 'chakram_cloud_tick_seconds', 0.5, NULL, 'seconds', 'Chakram - Shuriken Cloud: the interval between the cloud''s ticks; each carries that share of the rune''s 200% a second. Power/DemonHunter_Chakram.pow SF_9 ''E: Buff Tick Rate'' = 0.5'),
('demonhunter', 'elemental_arrow_ball_seek_yards', 15.0, NULL, 'yards', 'Elemental Arrow - Ball Lightning: how far from the ball an enemy is shocked. Power/DemonHunter_ElementalArrow.pow SF_22 ''RuneB: Seek Radius'' = 15'),
('demonhunter', 'elemental_arrow_ball_shock_delay_seconds', 0.1, NULL, 'seconds', 'Elemental Arrow - Ball Lightning: the pause between the two shocks of one tick; each is half the rune''s damage (SF_26 ''RuneB: Lightning Damage Scalar'' = 1.5 against the sheet''s 300%). Power/DemonHunter_ElementalArrow.pow SF_24 ''RuneB: Delay between shocks'' = 0.1'),
('demonhunter', 'elemental_arrow_ball_tick_seconds', 0.7, NULL, 'seconds', 'Elemental Arrow - Ball Lightning: the interval between the ball''s shocks. Power/DemonHunter_ElementalArrow.pow SF_21 ''RuneB: Tick Interval'' = 0.70'),
('demonhunter', 'elemental_arrow_cone_degrees', 120.0, NULL, 'degrees', 'Elemental Arrow - Frost Arrow: the width of the cone, behind the enemy struck, that the split arrows fly into. Power/DemonHunter_ElementalArrow.pow SF_14 ''RuneA: Conal Freeze Angle'' = 120'),
('demonhunter', 'elemental_arrow_cone_delay_seconds', 0.17, NULL, 'seconds', 'Elemental Arrow - Frost Arrow: the pause between the first arrow''s hit and the split arrows''. Power/DemonHunter_ElementalArrow.pow SF_16 ''RuneA: Conal Hit Delay Time'' = 0.17'),
('demonhunter', 'elemental_arrow_cone_radius_yards', 35.0, NULL, 'yards', 'Elemental Arrow - Frost Arrow: how far from the enemy struck the split arrows look for enemies. Power/DemonHunter_ElementalArrow.pow SF_13 ''RuneA: Conal Freeze Radius'' = 35'),
('demonhunter', 'elemental_arrow_immolation_tick_seconds', 0.5, NULL, 'seconds', 'Elemental Arrow - Immolation Arrow: the interval between the burning ground''s ticks; each carries that share of the rune''s 315%. Power/DemonHunter_ElementalArrow.pow SF_2 ''RuneC: AoE DoT Tickrate'' = 0.5'),
('demonhunter', 'elemental_arrow_slow_projectile_yards_per_second', 24.0, NULL, 'yards per second', 'Elemental Arrow - Ball Lightning and Nether Tentacles: how fast the ball and the tentacle fly. The power file gives 0.4 (SF_20 ''RuneB: Projectile Speed'', SF_29 ''RuneD: Projectile Speed''); a power-file speed is yards per frame at 60 frames a second (AGENTS.md ''Numbers''), so 0.4 reads as 24 yards a second'),
('demonhunter', 'elemental_arrow_tentacle_radius_yards', 6.0, NULL, 'yards', 'Elemental Arrow - Nether Tentacles: how far from the tentacle an enemy is struck. Power/DemonHunter_ElementalArrow.pow SF_31 ''RuneD: Tentacles Radius'' = 6'),
('demonhunter', 'elemental_arrow_tentacle_tick_seconds', 0.35, NULL, 'seconds', 'Elemental Arrow - Nether Tentacles: the interval between the tentacle''s strikes. Power/DemonHunter_ElementalArrow.pow SF_30 ''RuneD: Tick Interval'' = 0.35'),
('demonhunter', 'elemental_arrow_travel_yards', NULL, 60.0, 'yards', 'Elemental Arrow - Ball Lightning and Nether Tentacles: how far the ball and the tentacle fly before they end. The power file gives no distance; the skill''s range, 60 yards (skill_targeting.csv, q-1021-46 (a)). A placeholder for the PM to card'),
('demonhunter', 'entangling_shot_search_yards', 80.0, NULL, 'yards', 'Entangling Shot: how far from the enemy hit the shot looks for the other enemies it entangles (nearest first, up to the sheet''s count). The sheet says only ''entangles up to N enemies'' and gives no distance; Power/X1_DemonHunter_EntanglingShot.pow SF_17 ''Jump Search Radius'' = 80'),
('demonhunter', 'entangling_shot_shock_collar_tick_seconds', NULL, 0.5, 'seconds', 'Entangling Shot - Shock Collar: the interval between the ticks of the Lightning the entangled enemies take over the rune''s 2 seconds (80% in all). The sheet gives the total and the seconds, and the power file no tick length (SF_8 ''Electrical Damage Scalar'' = 0.40 reads as a share for each second); the designer''s standing default for a damage over time, 0.5 seconds (2026-10-22)'),
('demonhunter', 'evasive_fire_enemies_hit', 3.0, NULL, 'count', 'Evasive Fire: how many enemies the bolts hit in all, the enemy aimed at and the nearest ones beside it (the sheet says the primary enemy and two additional ones). Power/X1_DemonHunter_EvasiveFire.pow SF_24 ''B: Max Monsters Hit'' = 3'),
('demonhunter', 'evasive_fire_flip_search_degrees', 60.0, NULL, 'degrees', 'Evasive Fire: the width of the cone in front of the Demon Hunter in which an enemy sets off the backflip. Power/X1_DemonHunter_EvasiveFire.pow SF_6 ''Melee Search Angle'' = 60 (the file gives no unit; read as degrees)'),
('demonhunter', 'evasive_fire_flip_search_yards', 25.0, NULL, 'yards', 'Evasive Fire: how near an enemy in front of the Demon Hunter must be for the backflip (and Hardened''s armor instead of it) to happen. The sheet says only ''an enemy in front of you at close range''; Power/X1_DemonHunter_EvasiveFire.pow SF_5 ''Melee Safety Radius'' = 25'),
('demonhunter', 'evasive_fire_spread_degrees', 50.0, NULL, 'degrees', 'Evasive Fire: the width of the cone, centred on the enemy aimed at, that the enemies beside it must stand in to be hit. Power/X1_DemonHunter_EvasiveFire.pow SF_26 ''B: Angle'' = 50 (the file gives no unit; read as degrees, and read for every rune)'),
('demonhunter', 'grenade_cache_spread_degrees', 15.0, NULL, 'degrees', 'Grenade - Grenade Cache: the angle between one grenade of the fan and the next. Power/DemonHunter_Grenades.pow SF_11 ''Projectile Spread Angle'' = Rune_B ? 25 : 15, so 15 for Grenade Cache (the file gives no unit; read as degrees; Cluster Grenades'' 25 is not used, the file does not say what it spreads)'),
('demonhunter', 'grenade_cloud_chill_pct', 60.0, NULL, 'percent', 'Grenade - Cold Grenade: how much the cloud slows the enemies standing in it (Chill). Power/DemonHunter_Grenades.pow SF_34 ''A: Chill Amount'' = 0.60'),
('demonhunter', 'grenade_cloud_radius_yards', 6.0, NULL, 'yards', 'Grenade - Cold Grenade: the radius of the cloud the grenade leaves. Power/DemonHunter_Grenades.pow SF_5 ''A: Cloud Radius'' = 6'),
('demonhunter', 'grenade_cloud_tick_seconds', 0.5, NULL, 'seconds', 'Grenade - Cold Grenade: the interval between the cloud''s ticks. Power/DemonHunter_Grenades.pow SF_27 ''A: Damage Period'' = 0.5'),
('demonhunter', 'grenade_cluster_min_throw_yards', 8.0, NULL, 'yards', 'Grenade - Cluster Grenades: the same minimum throw distance for this rune. Power/DemonHunter_Grenades.pow SF_1 ''Min Throw Distance'' = Rune_B ? 8 : 6 (rune B is Cluster Grenades)'),
('demonhunter', 'grenade_cluster_pulse_seconds', 0.6, NULL, 'seconds', 'Grenade - Cluster Grenades: the time between one pulse and the next. Power/DemonHunter_Grenades.pow SF_12 ''B: Pulse Duration'' = 0.6 (the file does not say whether it is the gap between pulses or the length of them all; read as the gap)'),
('demonhunter', 'grenade_cluster_pulses', 3.0, NULL, 'count', 'Grenade - Cluster Grenades: how many pulses share the rune''s 200% weapon damage. The sheet says ''over a 9 yard radius''; Power/DemonHunter_Grenades.pow SF_28 ''B: Extra Pulse'' = 2 more than the first, and SF_17 divides the damage by that count plus one (1.6 x 1.25 / 3 = 0.667 a pulse, 200% in all)'),
('demonhunter', 'grenade_min_throw_yards', 6.0, NULL, 'yards', 'Grenade: a grenade aimed nearer than this to the Demon Hunter lands this far away, along the line of the aim. The sheet does not say; Power/DemonHunter_Grenades.pow SF_1 ''Min Throw Distance'' = Rune_B ? 8 : 6, so 6 for the skill and every rune but Cluster Grenades'),
('demonhunter', 'hungering_arrow_seek_after_pierce_yards', 20.0, NULL, 'yards', 'Hungering Arrow: how far from the enemy it pierced the arrow looks for the next one to strike. The sheet says only ''seeks out enemies'' and gives no distance; Power/DemonHunter_HungeringArrow.pow SF_13 ''Search Radius After Pierce'' = 20'),
('demonhunter', 'hungering_arrow_shatter_cone_degrees', 50.0, NULL, 'degrees', 'Hungering Arrow - Shatter Shot: the width of the cone behind the pierced enemy that the split arrows fly into, centred on the way the arrow was flying. Power/DemonHunter_HungeringArrow.pow SF_19 ''B: Cone Size Behind Target'' = 50 (the file gives no unit; read as degrees). 360 sends an arrow to any enemy around'),
('demonhunter', 'hungering_arrow_shatter_seek_yards', 11.0, NULL, 'yards', 'Hungering Arrow - Shatter Shot: how far from the pierced enemy the split arrows look for enemies to strike. Power/DemonHunter_HungeringArrow.pow SF_4 ''B: Search Radius'' = 11'),
('demonhunter', 'hungering_arrow_travel_yards', 90.0, NULL, 'yards', 'Hungering Arrow: how far from where it was shot the arrow can still pierce on to another enemy (the first enemy is the skill''s range, skill_targeting.csv). Power/DemonHunter_HungeringArrow.pow SF_14 ''Projectile Max Dist from Cast Location'' = 90'),
('demonhunter', 'impale_chemical_burn_tick_seconds', NULL, 0.5, 'seconds', 'Impale - Chemical Burn: the interval between the ticks of the burn. The sheet gives the total (500% over 2 seconds) and the power file no tick length; the designer''s standing default for a burn, 0.5 seconds (2026-10-22)'),
('demonhunter', 'impale_impact_knockback_yards', 5.0, NULL, 'yards', 'Impale - Impact: how far the knockback throws the enemy hit. Power/DemonHunter_Impale.pow SF_4 ''B: Knockback Magnitude'' = 5'),
('demonhunter', 'impale_pierce_length_yards', 60.0, NULL, 'yards', 'Impale - Overpenetration: how far the knife flies along the line through the enemy hit, so how far it pierces. Power/DemonHunter_Impale.pow SF_14 ''Max Target Distance'' = 60 (also the skill''s cast range, skill_targeting.csv)'),
('demonhunter', 'impale_pierce_width_yards', NULL, 3.0, 'yards', 'Impale - Overpenetration: how wide the line the knife pierces along is. Neither the sheet nor Power/DemonHunter_Impale.pow gives a width; the designer''s standing default for a line attack, 3 yards (2026-10-22)'),
('demonhunter', 'impale_ricochet_damage_factor', 1.0, NULL, 'multiplier', 'Impale - Ricochet: the share of the hit each bounce keeps of the one before. Power/DemonHunter_Impale.pow SF_16 ''D: Damage Decay Per Bounce'' = 1.0, so a bounce loses nothing'),
('demonhunter', 'passive_refresh_seconds', NULL, 0.25, 'seconds', 'Demon Hunter passives: the interval between the checks that keep a passive''s sheet contribution right when the passive is slotted or taken out (Blood Vengeance''s larger Hatred pool). No power file gives one; the designer''s standing default for a trigger check, 0.25 seconds (2026-10-22)'),
('demonhunter', 'rapid_fire_bombardment_shots_per_attack', 3.0, NULL, 'count', 'Rapid Fire - Bombardment: the same for the grenades, which come at half the rate. Power/DemonHunter_RapidFire.pow SF_21 ''A: Crimson Speed Multiplier'' = 3'),
('demonhunter', 'rapid_fire_grenade_range_yards', 50.0, NULL, 'yards', 'Rapid Fire - Bombardment: how far a grenade flies. Power/DemonHunter_RapidFire.pow SF_15 ''A: Max Grenade Range'' = 50'),
('demonhunter', 'rapid_fire_pierce_length_yards', 60.0, NULL, 'yards', 'Rapid Fire - High Velocity: how far an arrow flies along the line it pierces on. The skill''s range, 60 yards (skill_targeting.csv; Power/DemonHunter_RapidFire.pow AttackRadius)'),
('demonhunter', 'rapid_fire_pierce_width_yards', NULL, 3.0, 'yards', 'Rapid Fire - High Velocity: how wide the line an arrow pierces along is. Neither the sheet nor the power file gives a width; the designer''s standing default for a line attack, 3 yards (2026-10-22)'),
('demonhunter', 'rapid_fire_rocket_range_yards', 50.0, NULL, 'yards', 'Rapid Fire - Fire Support: how far from the Demon Hunter a rocket looks for an enemy to home on. Power/DemonHunter_RapidFire.pow SF_25 ''C: Homing Rocket Search Radius'' = 50'),
('demonhunter', 'rapid_fire_rocket_warmup_seconds', 0.7, NULL, 'seconds', 'Rapid Fire - Fire Support: how long into the channel the first rocket waits. Power/DemonHunter_RapidFire.pow SF_12 ''C: Damage Delay Warmup'' = 0.7'),
('demonhunter', 'rapid_fire_shots_per_attack', 6.0, NULL, 'count', 'Rapid Fire: how many shots a second of attack speed holds; the sheet''s 685% is for that second, so a shot carries a sixth, and the channel''s 6 Hatred a second a sixth too. Power/DemonHunter_RapidFire.pow SF_20 ''Base Speed Multiplier'' = 6 (SF_1 ''Shot Period'' = 1 / (attacks per second x it))'),
('demonhunter', 'shadow_power_life_on_hit_healing_share', 0.05, NULL, 'multiplier', 'Shadow Power: the share of D3''s Healing table at the player''s level (src/combat/dc_healing_table.h) that the Life per Hit is; the sheet''s 26821 is it at level 70. Power/DemonHunter_ShadowPower.pow SF_1 ''Life On Hit Base'' = 0.05 * Table(Healing,Effective_Level), SF_8 ''E: Life On Hit Bonus'' the same'),
('demonhunter', 'smoke_screen_movement_speed_pct', 15.0, NULL, 'percent', 'Smoke Screen: the movement speed gained while invisible by every rune but Displacement (which states its own 100). The tooltip names none; Power/DemonHunter_SmokeScreen.pow SF_12 ''E: Movement speed bonus'' = Rune_E ? 1.0 : 0.15'),
('demonhunter', 'smoke_screen_regen_tick_seconds', NULL, 0.5, 'seconds', 'Smoke Screen - Healing Vapors: the interval between the Life shares it gives while invisible (15% of the maximum Life for each second, split over the shares). Neither the power file (Power/DemonHunter_SmokeScreen.pow gives only SF_10 ''C: Heal Percent'' = 0.15) nor the tooltip (''Regenerate 15% Life while invisible'') gives a tick rate; the designer''s standing default for a damage over time, 0.5 seconds (2026-10-22), which the Architect rules a heal over time follows'),
('demonhunter', 'steady_aim_check_seconds', 0.5, NULL, 'seconds', 'Steady Aim: the interval between the checks for an enemy within its radius (Power/DemonHunter_Passive_SteadyAim.pow SF_3 ''Check Frequency'' = 0.5)'),
('demonhunter', 'steady_aim_duration_seconds', 0.7, NULL, 'seconds', 'Steady Aim: how long a clear check holds the damage bonus, a little more than the next check (Power/DemonHunter_Passive_SteadyAim.pow SF_2 ''Damage Increase Duration'' = SF_3 + 0.2)'),
('demonhunter', 'vault_action_shot_interval_seconds', 0.1, NULL, 'seconds', 'Vault - Action Shot: the pause between one arrow and the next. Power/DemonHunter_Vault.pow SF_3 ''C: Fire interval'' = 0.1'),
('demonhunter', 'vault_action_shot_range_yards', 35.0, NULL, 'yards', 'Vault - Action Shot: how far from the Demon Hunter an arrow looks for an enemy (''nearby enemies''). The power file gives no search radius of its own; the skill''s range, 35 yards (skill_targeting.csv; Power/DemonHunter_Vault.pow SF_10 ''Base: Range'' = 35, AttackRadius 35), as Rapid Fire''s pierce length takes its skill''s range'),
('demonhunter', 'vault_knockback_yards', NULL, 5.0, 'yards', 'Vault - Rattling Roll: how far an enemy vaulted through is knocked away. The tooltip says ''knocked away'' and the power file (Power/DemonHunter_Vault.pow) gives no distance. A placeholder for the PM to card: Impale - Impact''s 5 yards (impale_impact_knockback_yards, SF_4) stands in'),
('demonhunter', 'vault_stun_area_yards', 8.0, NULL, 'yards', 'Vault - Rattling Roll: how far from the Demon Hunter an enemy is looked for each check. Power/DemonHunter_Vault.pow SF_7 ''E: Stun Area'' = 8'),
('demonhunter', 'vault_stun_check_seconds', 0.1, NULL, 'seconds', 'Vault - Rattling Roll: the interval between the checks of the box while the Demon Hunter vaults. Power/DemonHunter_Vault.pow SF_18 ''E: Stun While Vaulting Frequency'' = 0.1'),
('demonhunter', 'vault_stun_strip_length_yards', 5.0, NULL, 'yards', 'Vault - Rattling Roll: how long the box is that travels with the Demon Hunter and stuns the enemies in it. Power/DemonHunter_Vault.pow SF_17 ''E: Stun While Vaulting Length'' = 5'),
('demonhunter', 'vault_stun_strip_width_yards', 5.0, NULL, 'yards', 'Vault - Rattling Roll: how wide the box is. Power/DemonHunter_Vault.pow SF_16 ''E: Stun While Vaulting Width'' = 5'),
('demonhunter', 'vault_trail_tick_seconds', 0.2, NULL, 'seconds', 'Vault - Trail of Cinders: the interval between the fire''s ticks on the enemies standing in it; each carries that share of the rune''s 300% over 3 seconds. Power/DemonHunter_Vault.pow SF_12 ''A: Fire Trail Tick Rate'' = 0.2'),
('demonhunter', 'vault_trail_width_yards', NULL, 3.0, 'yards', 'Vault - Trail of Cinders: how wide the trail of fire is, along the path the vault takes. Neither the sheet nor the power file gives a width; the designer''s standing default for a line attack, 3 yards (2026-10-22)'),
('demonhunter', 'vengeance_missile_search_yards', 60.0, NULL, 'yards', 'Vengeance: how far from the Demon Hunter the homing rockets look for an enemy (Power/X1_DemonHunter_Vengeance.pow SF_5 ''Missiles: Search Radius'' = 60)'),
('demonhunter', 'vengeance_mortar_max_range_yards', 60.0, NULL, 'yards', 'Vengeance - Personal Mortar: the farthest an enemy may be for a grenade to be thrown at it (Power/X1_DemonHunter_Vengeance.pow SF_33 ''C: Mortar Max Range'' = 60)'),
('demonhunter', 'vengeance_mortar_min_range_yards', 20.0, NULL, 'yards', 'Vengeance - Personal Mortar: the nearest an enemy may be for a grenade to be thrown at it, ''outside melee range'' (Power/X1_DemonHunter_Vengeance.pow SF_32 ''C: Mortar Min Range'' = 20)'),
('demonhunter', 'vengeance_mortar_radius_yards', 6.0, NULL, 'yards', 'Vengeance - Personal Mortar: how wide a grenade bursts (Power/X1_DemonHunter_Vengeance.pow SF_31 ''C: Mortar Explosion Radius'' = 6 x the Grenadier passive''s radius modifier, which is 1 until that passive is built)'),
('demonhunter', 'vengeance_seethe_tick_seconds', NULL, 0.5, 'seconds', 'Vengeance - Seethe: the interval between the Hatred shares it pays while it lasts (''Gain 10 Hatred per second''). Neither the power file (Power/X1_DemonHunter_Vengeance.pow gives only SF_39 ''E: Hatred Regeneration Bonus'' = 10) nor the tooltip gives a tick; the designer''s standing default for a damage over time, 0.5 seconds (2026-10-22), which the Architect rules a heal over time follows, read the same for a resource regenerated over time'),
('demonhunter', 'vengeance_shadow_ally_freeze_cooldown_seconds', 3.0, NULL, 'seconds', 'Vengeance - From the Shadows: how long an enemy frozen by an ally cannot be frozen again (Power/X1_DemonHunter_Vengeance.pow SF_45 ''A: Stun Cooldown per enemy'' = SF_42 x 1.0, SF_42 = 3)'),
('demonhunter', 'vengeance_shadow_ally_range_yards', 45.0, NULL, 'yards', 'Vengeance - From the Shadows: how far from the Demon Hunter the allies come out of the shadows (Power/X1_DemonHunter_Vengeance.pow SF_43 ''A: Shadow Ally summon radius'' = 45)'),
('demonhunter', 'vengeance_side_cannon_multiplier', 1.0, NULL, 'count', 'Vengeance - Side Cannons: the split-shot multiplier of the cannons, so half as many shots as the side guns (Power/X1_DemonHunter_Vengeance.pow SF_14 = 1 for Rune_D)'),
('demonhunter', 'vengeance_split_shot_cooldown_attacks', 0.9, NULL, 'multiplier', 'Vengeance: the side guns'' internal cooldown, as a share of one attack''s length: 0.9 / attacks a second (Power/X1_DemonHunter_Vengeance.pow SF_9 ''Split-Shot: Internal Cooldown Time'')'),
('demonhunter', 'vengeance_split_shot_multiplier', 2.0, NULL, 'count', 'Vengeance: the file''s split-shot multiplier the sheet''s four side guns are for (Power/X1_DemonHunter_Vengeance.pow SF_14 ''Split-Shot: Number Multiplier'' = 2 for every rune but Side Cannons)'),
('demonhunter', 'vengeance_split_shot_offset_yards', 2.5, NULL, 'yards', 'Vengeance: how far to the side of the Demon Hunter a side gun''s shot starts (Power/X1_DemonHunter_Vengeance.pow SF_38 ''Split-Shot: Offset from Player'' = 2.5)'),
('demonhunter', 'vengeance_split_shot_range_yards', 80.0, NULL, 'yards', 'Vengeance: how far a side gun''s piercing shot reaches (Power/X1_DemonHunter_Vengeance.pow SF_10 ''Split-Shot: Range'' = 80)'),
('demonhunter', 'vengeance_split_shot_spread_degrees', 6.0, NULL, 'degrees', 'Vengeance: how far across from the smallest angle a side gun''s shot may fall (Power/X1_DemonHunter_Vengeance.pow SF_12 ''Split-Shot: Spread Angle Delta'' = 6)'),
('demonhunter', 'vengeance_split_shot_spread_min_degrees', -2.0, NULL, 'degrees', 'Vengeance: the smallest angle a side gun''s shot takes off the line to the enemy aimed at (Power/X1_DemonHunter_Vengeance.pow SF_11 ''Split-Shot: Spread Angle Min'' = -2)'),
('demonhunter', 'vengeance_split_shot_width_yards', NULL, 3.0, 'yards', 'Vengeance: how wide the line of a side gun''s shot is. The power file gives the shot an auto-aim width (SF_13 = 15) and no line width; the designer''s standing default for a line attack, 3 yards (2026-10-22)'),
('economy', 'gem_vendor_gold', NULL, 0.0, 'gold', 'Codex literal audit 123; mod-diablocraft/scripts/generate_crafting.py:165; Gem vendor buy/sell prices; origin: none found; Both prices disabled; repeated same-line zero is one policy row.'),
('economy', 'item_sell_divisor', 25.0, NULL, 'count', 'ruling 2026-10-04 q-1004-08 (diablocraft-item-base-sell-price); a vendor pays floor(D3 ItemTable.Cost / this) for a base item (data/d3/base_item_costs.csv); d3_value 25 is D3''s own: Inventory.SellItem pays Math.Floor(item.GetPrice() / 25f), blizzless-diiis 6292f950aed3b29c58f35ce55caff6fd6c9d16b5 src/DiIiS-NA/D3-GameServer/GSSystem/PlayerSystem/Inventory.cs:327-337 (docs/research/item-sell-prices.md 2.2); value blank = D3''s; a change needs generate_sql.py rerun and its items_0021_item_sell_price.sql applied, a .dc tunables set does not move SellPrice.'),
('economy', 'legacy_gold_bar_stack_count', NULL, 2147483647.0, 'count', 'Codex literal audit 112; mod-diablocraft/scripts/generate_crafting.py:147; Legacy Gold Bar maximum stack; origin: none found; Chosen inventory stack size equals signed-int ceiling; legacy denomination is retired.'),
('economy', 'legendary_gem_sell_gold', NULL, 16.0, 'gold', 'the designer, card q-1006-04 (docs/decisions.md 2026-10-06, diablocraft-ozl9): the price a vendor pays for any legendary gem item, written to SellPrice as it is (this project''s gold is the core''s money unit, dc_economy.h CopperPerGold 1, as gem_vendor_gold is). The buy price stays gem_vendor_gold (0): no vendor sells them. Regenerate generate_legendary_gem_items.py and apply its world migration'),
('economy', 'starter_satchel_count', NULL, 2.0, 'count', 'Codex literal audit 36; mod-diablocraft/src/common/dc_world.cpp:38; Satchels granted to each character; origin: comment above GrantStarterBags; Also sets existing-character top-up target.'),
('economy', 'stash_launch_tabs', NULL, 1.0, 'count', 'audit row 31 LaunchTabs; decisions.md 2026-09-10 "one tab free and four more purchasable"'),
('economy', 'stash_max_tabs', NULL, 5.0, 'count', 'audit row 30 MaxTabs; decisions.md 2026-09-10, quoted in dc_stash.h''s header comment. Ours: D3 sells more than five'),
('economy', 'stash_tab_2_price_gold', NULL, 100000.0, 'gold', 'ruling 2026-10-04 q-1004-05 (q-1003-30); tab 2 price; regenerate generate_account_economy.py and apply its stash migration.'),
('economy', 'stash_tab_3_price_gold', NULL, 100000.0, 'gold', 'ruling 2026-10-04 q-1004-05 (q-1003-30); tab 3 price; regenerate generate_account_economy.py and apply its stash migration.'),
('economy', 'stash_tab_4_price_gold', NULL, 100000.0, 'gold', 'ruling 2026-10-04 q-1004-05 (q-1003-30); tab 4 price; regenerate generate_account_economy.py and apply its stash migration.'),
('economy', 'stash_tab_5_price_gold', NULL, 100000.0, 'gold', 'ruling 2026-10-04 q-1004-05 (q-1003-30); tab 5 price; regenerate generate_account_economy.py and apply its stash migration.'),
('economy', 'tester_coffer_gems', NULL, 20.0, 'count', 'the designer-approved docs/briefs/codex-tester-coffer-brief.md 2026-09-23; target per Flawless Royal colour.'),
('economy', 'tester_coffer_gold', NULL, 500000000000.0, 'gold', 'the designer-approved docs/briefs/codex-tester-coffer-brief.md 2026-09-23; account gold target; Torment dc_economy.h CopperPerGold is 1.'),
('economy', 'tester_coffer_materials', NULL, 100000.0, 'count', 'the designer-approved docs/briefs/codex-tester-coffer-brief.md 2026-09-23; target per tracked account material.'),
