('witchdoctor', 'corpse_spiders_hits_per_spider', 3.0, NULL, 'count', 'Corpse Spiders: how many times a spider bites in its life; the sheet''s total is shared among every bite of every spider. Power/Witchdoctor_CorpseSpider.pow SF_24 ''Spider Average Hits'' = 3'),
('witchdoctor', 'corpse_spiders_impact_pct', 1.0, NULL, 'percent', 'Corpse Spiders: what the jar itself hits for where it breaks; the spiders'' and the queen''s damage is theirs. Power/Witchdoctor_CorpseSpider.pow SF_1 ''Impact Weapon Scalar'' = 0.01'),
('witchdoctor', 'corpse_spiders_lifetime_seconds', 4.0, NULL, 'seconds', 'Corpse Spiders: how long a spider lives, inside which its bites fall. Power/Witchdoctor_CorpseSpider.pow SF_3 ''Spider Lifetime'' = 4'),
('witchdoctor', 'corpse_spiders_queen_area_yards', 10.0, NULL, 'yards', 'Corpse Spiders - Spider Queen: how far from the jar the queen''s pulses reach. Power/Witchdoctor_CorpseSpider.pow SF_13 ''B: Mom Spider Area'' = 10'),
('witchdoctor', 'corpse_spiders_queen_pulse_seconds', 0.25, NULL, 'seconds', 'Corpse Spiders - Spider Queen: the interval between her pulses, each an even share of the rune''s 2625% over 15 seconds. Power/Witchdoctor_CorpseSpider.pow SF_19 ''B: Mom Spider Pulse Frequency'' = 0.25'),
('witchdoctor', 'corpse_spiders_reach_yards', NULL, 10.0, 'yards', 'Corpse Spiders: how far from the jar a spider finds an enemy to bite (Leaping Spiders'' own is the rune''s radius_yards). Neither the sheet nor the power file (Power/Witchdoctor_CorpseSpider.pow) gives a spider''s search radius; the designer''s answer on card q-1021-102 is 10 yards (2026-10-23)'),
('witchdoctor', 'corpse_spiders_slow_seconds', 1.5, NULL, 'seconds', 'Corpse Spiders - Medusa Spiders: how long a bite''s slow lasts (its chance and amount are the rune''s proc_chance_pct and slow_pct). Power/Witchdoctor_CorpseSpider.pow SF_5 ''E: Slow Duration'' = 1.5'),
('witchdoctor', 'fetish_life_pct', NULL, 35.0, 'percent', 'Fetish Army and Fetish Sycophants: a Fetish''s Life as a share of the Witch Doctor''s maximum Life, as the Zombie Dog''s is. The designer''s value (q-1021-95, 2026-10-22): no power file states a Fetish''s Life.'),
('witchdoctor', 'fetish_ring_max_yards', 14.0, NULL, 'yards', 'Fetish Army: the outer edge of the ring the Fetishes appear on round the Witch Doctor. Power/Witchdoctor_FetishArmy.pow SF_1 ''Spawn Radius Max'' = 14'),
('witchdoctor', 'fetish_ring_min_yards', 9.0, NULL, 'yards', 'Fetish Army: the inner edge of the ring the Fetishes appear on round the Witch Doctor. Power/Witchdoctor_FetishArmy.pow SF_4 ''Spawn Radius Min'' = 9'),
('witchdoctor', 'fetish_spawn_interval_seconds', 0.1, NULL, 'seconds', 'Fetish Army: the seconds between one Fetish appearing and the next. Power/Witchdoctor_FetishArmy.pow SF_2 ''Interval Between Spawns'' = 0.1'),
('witchdoctor', 'fetish_sycophants_max', 15.0, NULL, 'count', 'Fetish Sycophants: the most Fetishes the passive has summoned at once. Power/Witchdoctor_Passive_FetishSycophants.pow SF_4 ''Max Sycophants'' = 15'),
('witchdoctor', 'firebomb_bounce_distance_yards', 14.0, NULL, 'yards', 'Firebomb - Roll the Bones: how far from where the skull exploded it bounces to the next enemy. Power/Witchdoctor_Firebomb.pow SF_8 ''B: Additional Bounce Distance'' = 14'),
('witchdoctor', 'firebomb_flash_delay_seconds', 0.1, NULL, 'seconds', 'Firebomb - Flash Fire: the pause between one bounce and the next. Power/Witchdoctor_Firebomb.pow SF_17 ''E: Delay Between Bounces'' = 0.1'),
('witchdoctor', 'firebomb_flash_radius_yards', 25.0, NULL, 'yards', 'Firebomb - Flash Fire: how far from an enemy the next one is chosen to bounce to. Power/Witchdoctor_Firebomb.pow SF_18 ''E: Target Selection Radius'' = 25'),
('witchdoctor', 'firebomb_pit_tick_seconds', NULL, 0.5, 'seconds', 'Firebomb - Fire Pit: the interval between the pool''s ticks; each carries that share of the rune''s 60% over 3 seconds. Neither the sheet nor the power file (Power/Witchdoctor_Firebomb.pow gives SF_10 ''C: Pool Weapon Scalar'' = 0.20, SF_11, SF_12) gives a tick; the designer''s standing default for a burn tick, 0.5 seconds (2026-10-22)'),
('witchdoctor', 'firebomb_pyrogeist_range_yards', 30.0, NULL, 'yards', 'Firebomb - Pyrogeist: how far from the column it looks for the closest enemy. Power/Witchdoctor_Firebomb.pow SF_26 ''D: Target Area'' = 30'),
('witchdoctor', 'firebomb_pyrogeist_tick_seconds', 0.3, NULL, 'seconds', 'Firebomb - Pyrogeist: the interval between a column''s spews; each carries that share of the rune''s 880% over 6 seconds. Power/Witchdoctor_Firebomb.pow SF_25 ''D: Tick Rate'' = 0.30'),
('witchdoctor', 'gargantuan_cleave_degrees', 180.0, NULL, 'degrees', 'Gargantuan: the angle of its cleave, centred on the enemy it strikes. Power/Witchdoctor_Gargantuan_Cleave.pow SF_1 ''Cleave attack angle'' = 180'),
('witchdoctor', 'gargantuan_cleave_yards', 15.0, NULL, 'yards', 'Gargantuan: how far its cleave reaches. Power/Witchdoctor_Gargantuan_Cleave.pow SF_0 ''Cleave attack range'' = 15'),
('witchdoctor', 'gargantuan_life_pct', 50.0, NULL, 'percent', 'Gargantuan: the Gargantuan''s Life as a share of the Witch Doctor''s maximum Life (Zombie Handler raises it by its pet_life_pct). Power/Witchdoctor_Gargantuan.pow SF_10 ''Pet HP Scalar'' = 0.5; the base it multiplies is the Witch Doctor''s Life, the reading of zombie_dog_life_pct'),
('witchdoctor', 'gargantuan_swing_seconds', 3.0, NULL, 'seconds', 'Gargantuan: the seconds between its swings, the cooldown of its only basic attack, a cleave. Power/Witchdoctor_Gargantuan_Cleave.pow CooldownTime = 3'),
('witchdoctor', 'plague_of_toads_rain_radius_yards', 8.0, NULL, 'yards', 'Plague of Toads - Rain of Toads: how far from the enemy aimed at the rain strikes. Power/Witchdoctor_PlagueOfToads.pow SF_9 ''B: Rain Area'' = 8'),
('witchdoctor', 'plague_of_toads_rain_speed_bonus', 0.4, NULL, 'multiplier', 'Plague of Toads - Rain of Toads: how much faster the skill casts (the attacks a second are multiplied by 1 plus this). Power/Witchdoctor_PlagueOfToads.pow SF_1 ''Attack Speed Mult'' = 1.0 + 0.4 * MIN(1, Rune_B)'),
('witchdoctor', 'plague_of_toads_rain_tick_seconds', 0.5, NULL, 'seconds', 'Plague of Toads - Rain of Toads: the interval between the rain''s ticks; each carries that share of the rune''s 130% over 2 seconds. Power/Witchdoctor_PlagueOfToads.pow SF_11 ''B: Rain Tick Period'' = 0.5'),
('witchdoctor', 'poison_dart_shot_delay_seconds', 0.15, NULL, 'seconds', 'Poison Dart - Splinters: the pause between one dart and the next. Power/Witchdoctor_PoisonDart.pow SF_17 ''B: Shot Delay'' = 0.15 (the file''s auto-target angle and distance, SF_19 and SF_20, are not built: every dart flies at the enemy the cast was aimed at)'),
('witchdoctor', 'poison_dart_tick_seconds', NULL, 0.5, 'seconds', 'Poison Dart: the interval between the ticks of the poison every dart leaves and of Flaming Dart''s fire. Neither the sheet nor the power file gives one (Power/Witchdoctor_PoisonDart.pow gives only SF_9 ''Poison Duration'' = 2 and SF_3 ''A: Duration'' = 4); the designer''s standing default for a burn or bleed tick, 0.5 seconds (2026-10-22)'),
('witchdoctor', 'zombie_dog_life_pct', 35.0, NULL, 'percent', 'Summon Zombie Dogs: a Zombie Dog''s Life as a share of the Witch Doctor''s maximum Life (Zombie Handler raises it by its pet_life_pct). Power/Witchdoctor_SummonZombieDog.pow SF_17 ''Pet Hitpoints Scalar'' = 0.35; the file does not say what it multiplies, so the Witch Doctor''s Life is the reading, as the module''s other pets'),
('wizard', 'archmages_vicalyke_multiply_chance_pct', NULL, 50.0, 'percent', 'diablocraft-6cw6f (Archmage''s Vicalyke, legendary 016; docs/research/legendary-catalogue.csv row 352): the chance, in percent, that a Mirror Image killed by an enemy multiplies (one more Image appears where it stood, with the dead one''s remaining time) while the hat is worn. D3''s item text says only ''a chance'' and no source or Power file gives a number. The designer''s number: 50 (card q-1013-16, 2026-10-13, diablocraft-e8q7g). Blank reads 0: the power does nothing. 0 never, 100 always; set at run time with `.dc tunables set wizard archmages_vicalyke_multiply_chance_pct <n>`'),
('wizard', 'electrocute_jump_radius_yards', 15.0, NULL, 'yards', 'diablocraft-d00zm (Wizard Electrocute jumps as D3; decisions.md 2026-10-14): how far, in yards, Electrocute''s bolt jumps from the enemy it is on to the next (the nearest one it has not hit; Wizard::Jumps). D3''s: Power/Wizard_Electrocute.pow SF_2 ''Target Search Radius'' = 15 (decode_pow.py power Wizard_Electrocute; SF_15 ''Initial Target Search Radius'' 7 is the first target''s), and the community server reads SF_2 as the bounce search radius (reference/blizzless-diiis Wizard.cs WizardElectrocute: GetEnemiesInRadius(curTarget.Position, ScriptFormula(2), ...)). The PM''s default was 10 yd (the core''s magic chain default) on the reading that no source gave D3''s; SF_2 is that source, so the row carries D3''s 15 (PM defaults follow D3). The designer can set value to overrule. Blank or 0: the bolt does not jump'),
('wizard', 'energy_twister_hit_radius_yards', 8.0, NULL, 'yards', 'diablocraft-3ypq2: how far from a travelling twister''s centre an enemy is hit by each tick (one every interval_seconds, the first at once). d3_value is the skill''s radius, data/d3/skill_targeting.csv:38 (d3planner simulator/wizard.js:538). 0 hits nothing'),
('wizard', 'energy_twister_speed_yards_per_second', 15.0, 5.0, 'yards per second', 'diablocraft-3ypq2 (Energy Twister''s travel, ruling q-1013-17 (a)), diablocraft-1np46 (ruling q-1014-07): how fast a travelling twister (the base skill and every rune but Wicked Wind) wanders from the aim point. d3_value is d3planner''s (data/d3/wizard_skill_values.csv travel_speed_yards_per_second: simulator/wizard.js:543, 0.25 yards a frame at 60 frames). value is the designer''s final 5, neither the 3.3 the skill''s 20-yard range over its 6-second dot_duration_seconds gave nor D3''s 15. Blank value reads d3_value. 0 stands the twister still'),
('wizard', 'energy_twister_turn_interval_seconds', NULL, 1.0, 'seconds', 'diablocraft-3ypq2 (ruling q-1013-17 (a)): how often a travelling twister turns; the first second goes straight ahead from the Wizard toward the aim point. No source gives D3''s; 1 is the card''s default. 0 never turns'),
('wizard', 'energy_twister_turn_limit_degrees', NULL, 45.0, 'degrees', 'diablocraft-3ypq2 (ruling q-1013-17 (a)): the most a travelling twister turns at each turn, either way; each turn is random within it and forward-biased (the limit times the difference of two rolls, src/classes/wizard/dc_twister_math.h). No source gives D3''s wander; 45 is the card''s default. 0 is a straight path'),
('wizard', 'ray_of_frost_pierce_width_yards', NULL, 4.0, 'yards', 'diablocraft-n8eqs (Light of Grace, legendary 024; docs/research/legendary-catalogue.csv row 362; decisions.md 2026-10-13): how wide, in yards, Ray of Frost''s beam is while Light of Grace is worn, so it hits every enemy on its line. D3''s item text is only ''Ray of Frost now pierces.'' and no source gives Ray of Frost a beam width: 4 yd is BORROWED from Disintegrate''s line_pierce (skill_targeting.csv:32, d3planner simulator wizard.js:355, twice the half-width 2). The PM''s ruling, the designer may overrule it. Blank or 0 turns the pierce off.'),
('wizard', 'tal_rashas_elements_immunity_seconds', NULL, 8.0, 'seconds', 'diablocraft-fkcp2 (Tal Rasha''s Elements 2-piece, legendary set): the seconds the player is immune to an element after damage with it drops a Meteor of that type. D3''s set text says only ''immune to that element'' (data.json, the d3planner set text) and no source or Power file gives a duration; the designer set it to 8 (decisions.md 2026-10-16, card q-1016-09; the 4-piece''s resistances last 8 s too). Blank reads 0: the Meteor drops and there is no immunity. Set at run time with `.dc tunables set wizard tal_rashas_elements_immunity_seconds <n>`')
